/* Biz-Flights live integration: inventory is retrieved by a secure Node server.
   Flights are shown only when returned by Duffel; no fabricated live results. */
(() => {
  'use strict';
  const airports = [
    ['DAC','Dhaka','Bangladesh'],['CGP','Chattogram','Bangladesh'],['ZYL','Sylhet','Bangladesh'],
    ['KUL','Kuala Lumpur','Malaysia'],['BKK','Bangkok','Thailand'],['SIN','Singapore','Singapore'],
    ['DXB','Dubai','United Arab Emirates'],['JED','Jeddah','Saudi Arabia'],['LIS','Lisbon','Portugal'],
    ['MLA','Valletta','Malta'],['DPS','Denpasar (Bali)','Indonesia'],['KIX','Osaka','Japan'],
    ['BEG','Belgrade','Serbia'],['HKG','Hong Kong','Hong Kong'],['LHR','London','United Kingdom'],
    ['DEL','New Delhi','India'],['ICN','Seoul','South Korea'],['DOH','Doha','Qatar'],
    ['IST','Istanbul','Turkey'],['CCU','Kolkata','India'],['KTM','Kathmandu','Nepal'],
    ['BUD','Budapest','Hungary'],['WAW','Warsaw','Poland'],['BLQ','Bologna','Italy'],
    ['BCN','Barcelona','Spain'],['LCA','Larnaca','Cyprus'],['MSQ','Minsk','Belarus'],
    ['VTE','Vientiane','Laos'],['YYZ','Toronto','Canada'],['CDG','Paris','France'],
    ['FCO','Rome','Italy'],['SYD','Sydney','Australia'],['JFK','New York','United States'],
    ['NAN','Nadi','Fiji'],['MXP','Milan','Italy'],['AMS','Amsterdam','Netherlands'],
    ['VIE','Vienna','Austria'],['HEL','Helsinki','Finland'],['OTP','Bucharest','Romania'],
    ['NRT','Tokyo','Japan'],['EVN','Yerevan','Armenia'],['RMO','Chișinău','Moldova'],
    ['AUH','Abu Dhabi','United Arab Emirates'],['MCT','Muscat','Oman'],['RUH','Riyadh','Saudi Arabia'],
    ['FRA','Frankfurt','Germany'],['ZRH','Zurich','Switzerland'],['CMB','Colombo','Sri Lanka'],
    ['MEL','Melbourne','Australia'],['LAX','Los Angeles','United States']
  ].map(([code,city,country]) => ({code,city,country}));
  const carriers = ['Biman Bangladesh','US-Bangla Airlines','Emirates','Qatar Airways','Singapore Airlines','Turkish Airlines','Air Arabia','Thai Airways','Malaysia Airlines','Etihad Airways','Air India','Cathay Pacific','Lufthansa','British Airways'];
  const airlineCodes={'Biman Bangladesh':'BG','US-Bangla Airlines':'BS','Emirates':'EK','Qatar Airways':'QR','Singapore Airlines':'SQ','Turkish Airlines':'TK','Air Arabia':'G9','Thai Airways':'TG','Malaysia Airlines':'MH','Etihad Airways':'EY','Air India':'AI','Cathay Pacific':'CX','Lufthansa':'LH','British Airways':'BA'};
  const airlineColor={'BG':'#D62E30','BS':'#E22126','EK':'#D20C1F','QR':'#65143D','SQ':'#DEAA43','TK':'#C72331','G9':'#E72236','TG':'#6E438F','MH':'#B50D2D','EY':'#B99D71','AI':'#D8232C','CX':'#16685E','LH':'#0A2865','BA':'#173D81'};
  // Actual airline logo images are loaded by IATA code, not generated imitation marks.
  // The sources below provide logo artwork for airline identification, where available.
  // For guaranteed offline/production use, obtain permission and host licensed logo PNGs locally.
  const logoSources = code => [
    `${window.AIR_TICKET.api}airline-logo&code=${encodeURIComponent(code)}`, // same image used by PDF; prefer bundled assets
    `https://pics.avs.io/200/200/${encodeURIComponent(code)}.png`,
    `https://cdn.jsdelivr.net/gh/spydogenesis/airlines-logo@main/airlines-logo/200x200_v2/${encodeURIComponent(code)}.png`,
    `https://images.kiwi.com/airlines/64/${encodeURIComponent(code)}.png`
  ];
  function airlineBadge(name,code='',extra='') {
    const key=code||airlineCodes[name]||'EF', color=airlineColor[key]||'#2258ad';
    return `<span class="airline-brand ${extra}" style="--airline-color:${color}" title="${esc(name)}"><span class="airline-emblem">${ic('plane-small',20)}<b>${esc(key)}</b></span><img class="airline-real-logo" src="${logoSources(key)[0]}" data-logo-code="${esc(key)}" data-logo-try="0" loading="lazy" decoding="async" alt="${esc(name)} official brand logo" referrerpolicy="no-referrer" /></span>`;
  }
  // Capture load/error events for dynamically created results, chips, comparison and itinerary cards.
  document.addEventListener('load', event => {
    if (event.target.matches?.('img.airline-real-logo')) event.target.classList.add('is-loaded');
  }, true);
  document.addEventListener('error', event => {
    const img = event.target;
    if (!img.matches?.('img.airline-real-logo')) return;
    const sources = logoSources(img.dataset.logoCode || 'EF');
    const next = Number(img.dataset.logoTry || 0) + 1;
    if (next < sources.length) {
      img.dataset.logoTry = String(next);
      img.src = sources[next];
    } else {
      img.hidden = true; // Keep readable airline-code fallback, never a misleading imitation logo.
      img.classList.remove('is-loaded');
    }
  }, true);
  function loadSaved(){try{return JSON.parse(localStorage.getItem('ef_public_trips')||'[]').slice(0,12)}catch(_){return []}}
  function storeSaved(v){try{localStorage.setItem('ef_public_trips',JSON.stringify(v))}catch(_){}}
  function loadChecklist(){try{return JSON.parse(localStorage.getItem('ef_checklist')||'{}')}catch(_){return {}}}
  const featuredCodes = ['KUL','BKK','SIN','DXB','LHR','CDG','YYZ','IST'];
  const today = () => { let d = new Date(); return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0,10); };
  const addDays = (n, date=today()) => {let d = new Date(date+'T12:00:00'); d.setDate(d.getDate()+n);return d.toISOString().slice(0,10);};
  const fmtDate = date => {if(!date)return 'Choose date'; const d=new Date(date+'T12:00:00');return Number.isNaN(d.valueOf())?'Choose date':d.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});};
  const esc = s => String(s??'').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const safeDate = str => /^\d{4}-\d{2}-\d{2}$/.test(str||'') ? str : today();
  const iconPaths = {
    plane:'<path d="M17.5 21v-8.5L4 17l-2-2 15.5-7.5V3.5a2.5 2.5 0 0 1 5 0v17a2.5 2.5 0 0 1-5 0Z" transform="rotate(45 12 12)"/>',
    'plane-small':'<path d="M22 2 9.5 14.5"/><path d="m22 2-7.2 20-4-8-8-4Z"/>',
    calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',
    users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',
    location:'<path d="M20 10c0 5-8 11-8 11S4 15 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',
    'arrow-right':'<path d="M5 12h14m-6-6 6 6-6 6"/>',
    arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
    swap:'<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
    download:'<path d="M12 3v12m-4-4 4 4 4-4M5 17v4h14v-4"/>',
    file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h6"/>',
    search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',
    hotel:'<path d="M4 21V5l8-3 8 3v16M2 21h20M9 8h1m4 0h1M9 12h1m4 0h1M9 16h1m4 0h1M10 21v-4h4v4"/>',
    menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
    close:'<path d="M6 6 18 18M18 6 6 18"/>',
    star:'<path d="m12 2 3.2 6.8 7.3 1-5.3 5.1 1.3 7.1-6.5-3.5-6.5 3.5 1.3-7.1-5.3-5.1 7.3-1Z"/>',
    'chevron-down':'<path d="m6 9 6 6 6-6"/>',
    'chevron-up':'<path d="m6 15 6-6 6 6"/>',
    'chevron-left':'<path d="m15 18-6-6 6-6"/>',
    globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c-3 3-3 15 0 18M12 3c3 3 3 15 0 18"/>',
    sparkle:'<path d="m12 2 1.7 6.3L20 10l-6.3 1.7L12 18l-1.7-6.3L4 10l6.3-1.7L12 2ZM20 17l.5 1.5L22 19l-1.5.5L20 21l-.5-1.5L18 19l1.5-.5Z"/>',
    mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 6 10 8 10-8"/>',
    info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v5m0-8h.01"/>',
    credit:'<rect x="2" y="5" width="20" height="14" rx="2"/><path d="M2 10h20"/>',
    user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
    heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0l-1 1-1-1a5.5 5.5 0 0 0-7.8 7.8l8.8 8.6 8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
    'external-link':'<path d="M14 4h6v6M20 4l-9 9M20 14v6H4V4h6"/>',
    building:'<path d="M3 21h18M5 21V5l7-3 7 3v16M9 8h1m4 0h1M9 12h1m4 0h1M9 16h1m4 0h1"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
    minus:'<path d="M5 12h14"/>'
  };
  const ic = (name,size=19) => `<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.85" stroke-linecap="round" stroke-linejoin="round">${iconPaths[name]||iconPaths.sparkle}</svg>`;
  const findAirport = input => {let t=String(input||'').trim().toLowerCase();return airports.find(a=>a.code.toLowerCase()===t || `${a.city} (${a.code})`.toLowerCase()===t) || airports.find(a=>a.city.toLowerCase()===t) || (/^[a-z]{3}$/.test(t)?{code:t.toUpperCase(),city:t.toUpperCase(),country:'Airport'}:null);};
  const cityText = code => {const a=airports.find(a=>a.code===code);return a?`${a.city} (${a.code})`:code;};
  const airport = code => airports.find(a=>a.code===code)||{code:code||'---',city:code||'Airport',country:''};
  const defaultSegments = () => [{from:'',to:'',date:addDays(14)},{from:'',to:'',date:addDays(18)}];
  const state = {
    view:'home', tab:'flight', trip:'round', from:'',to:'', departure:addDays(14),returnDate:addDays(24),
    adults:1,children:0,infants:0,cabin:'Economy',passengersOpen:false,mobileMenu:false,
    segments:defaultSegments(), hotelCity:'',checkin:addDays(14),checkout:addDays(18),rooms:1,hotelGuests:2,
    error:'',search:null,selected:null,travellers:[],passportScan:{},faqOpen:0,destinationQuery:'',hotelSearch:null,modal:null,
    contactFeedback:'', newsletterFeedback:'', routeFilter:'all',sortBy:'cheapest',liveStopFilter:'all',live:null,usingDemo:false,compare:[],favorites:[],savedTrips:loadSaved(),checklist:loadChecklist(),toolMessage:''
  };
  const logo = () => `<a href="#/" class="brand" aria-label="Biz-Flights home"><span class="brand-mark">${ic('plane-small',24)}</span><span class="brand-name">biz-<span>flights</span><small>TRAVEL MADE SIMPLE</small></span></a>`;
  const btn = (label,act,cls='btn btn-primary',extra='') => `<button type="button" class="${cls}" data-action="${act}" ${extra}>${label}</button>`;
  const routes = ['home','individuals','agencies','destinations','guides','contact','about','results','travellers','review','hotel-results','tools','saved','pnr','documents'];
  const navigate = view => {state.view=routes.includes(view)?view:'home';state.mobileMenu=false;state.error='';location.hash=state.view==='home'?'/':'/'+state.view;render();window.scrollTo({top:0,behavior:'instant'});};
  function header(){ const links=[['Flights','home'],['Destinations','destinations'],['For agencies','agencies'],['Visa guides','guides'],['Travel tools','tools']];return `
    <div class="announcement"><span>${ic('sparkle',15)} Visa travel planning, made beautifully simple</span><a href="#/individuals">How it works ${ic('arrow-right',14)}</a></div>
    <header class="site-header"><div class="container header-inner">${logo()}
      <nav class="nav-links" aria-label="Main navigation">${links.map(([t,v])=>`<a class="${state.view===v?'active':''}" href="#/${v}">${t}</a>`).join('')}</nav>
      <div class="header-actions">${btn(ic('heart',16)+' Saved','saved','btn btn-quiet btn-sm')}${btn('Plan a trip '+ic('arrow-right',16),'start','btn btn-primary btn-sm')}<button aria-label="Toggle menu" class="menu-toggle" data-action="toggle-menu">${ic(state.mobileMenu?'close':'menu',24)}</button></div>
    </div>${state.mobileMenu?`<nav class="mobile-nav">${links.map(([t,v])=>`<a href="#/${v}">${t}</a>`).join('')}<a href="#/saved">Saved trips</a><a href="#/contact">Contact</a>${btn('Plan a trip','start','btn btn-primary')}</nav>`:''}</header>`;}
  function footer(){return `<footer class="footer"><div class="container"><div class="footer-top"><div class="footer-brand">${logo()}<p>Thoughtful travel planning for people going places. Explore routes, organize trip details and create a clearly marked travel itinerary.</p><div class="footer-trust">${ic('shield',17)} Transparent travel planning</div></div><div class="footer-col"><h4>Explore</h4><a href="#/individuals">For individuals</a><a href="#/agencies">For agencies</a><a href="#/destinations">Destinations</a><a href="#/guides">Visa guides</a><a href="#/tools">Travel tools</a><a href="#/saved">Saved routes</a></div><div class="footer-col"><h4>Resources</h4><a href="#/about">About us</a><a href="#/contact">Contact</a><a href="#/guides">How it works</a><a href="#/pnr">PNR verification</a><a href="#/documents">Documents & receipts</a><a href="#/">Flight search</a></div><div class="footer-col"><h4>Plan your journey</h4><p>Biz-Flights is a travel-planning demo. Schedules shown in demo mode are illustrative, not airline reservations.</p><a href="#/contact" class="footer-link">Get in touch ${ic('arrow-right',15)}</a></div></div></div></footer>`;}
  function airportField(label,key,iconName='plane-small',segIndex=null){const name=segIndex!==null?`seg-${segIndex}-${key}`:key;const current=segIndex!==null?state.segments[segIndex][key]:state[key];return `<div class="search-field airport-field"><label class="field-label" for="airport-${name}">${label}</label><span class="field-body">${ic(iconName,19)}<input id="airport-${name}" type="text" data-input="${name}" data-airport-entry="1" role="combobox" aria-controls="airport-options-${name}" aria-expanded="false" aria-autocomplete="list" aria-label="${label} airport or city" autocomplete="off" placeholder="Type city or airport" value="${esc(cityText(current))}" required /></span><span class="field-hint">${esc(airport(current).country||'Select from airport suggestions')}</span><div id="airport-options-${name}" class="airport-suggestions" role="listbox" hidden></div></div>`;}
  function dateField(label,key,value,segIndex=null){const name=segIndex!==null?`seg-${segIndex}-${key}`:key;return `<label class="search-field date-field"><span class="field-label">${label}</span><span class="field-body">${ic('calendar',19)}<input type="date" aria-label="${label}" data-input="${name}" min="${today()}" value="${esc(value)}" required /></span></label>`;}
  function airportList(){return '';}
  const airportFavorites=['DAC','LHR','DXB','KUL','SIN','DOH'];
  function setAirportState(name,value){
    if(name.startsWith('seg-')){const [,idx,key]=name.split('-');if(state.segments[+idx])state.segments[+idx][key]=value;}
    else if(name==='from'||name==='to')state[name]=value;
  }
  function drawAirportSuggestions(input){
    const parent=input.closest('.airport-field'),list=parent?.querySelector('.airport-suggestions');
    if(!list)return;
    const q=input.value.trim().toLowerCase();
    const matches=(q?airports.filter(a=>[a.city,a.country,a.code,`${a.city} (${a.code})`].some(v=>v.toLowerCase().includes(q))):airportFavorites.map(c=>airports.find(a=>a.code===c)).filter(Boolean)).slice(0,8);
    list.innerHTML=matches.length?matches.map((a,i)=>`<button type="button" class="airport-suggestion" role="option" id="${list.id}-item-${i}" data-airport-select="${esc(a.code)}" data-airport-target="${esc(input.dataset.input)}" aria-selected="false"><span class="airport-suggestion-main">${esc(a.city)} <b>${esc(a.code)}</b></span><small>${esc(a.country)}</small></button>`).join(''):'<div class="airport-none">No matching airport. Try an IATA code (e.g. DAC).</div>';
    document.querySelectorAll('.airport-suggestions').forEach(el=>{if(el!==list)el.hidden=true});
    document.querySelectorAll('input[data-airport-entry]').forEach(el=>{if(el!==input)el.setAttribute('aria-expanded','false')});
    list.hidden=false;input.setAttribute('aria-expanded','true');
  }
  function closeAirportSuggestions(){document.querySelectorAll('.airport-suggestions').forEach(el=>el.hidden=true);document.querySelectorAll('input[data-airport-entry]').forEach(el=>el.setAttribute('aria-expanded','false'));}
  function chooseAirport(name,code){const a=airports.find(a=>a.code===code);if(!a)return;setAirportState(name,a.code);const input=Array.from(document.querySelectorAll('input[data-airport-entry]')).find(el=>el.dataset.input===name);if(input){input.value=cityText(code);const hint=input.closest('.airport-field')?.querySelector('.field-hint');if(hint)hint.textContent=a.country;}closeAirportSuggestions();}
  document.addEventListener('focusin',event=>{if(event.target.matches?.('input[data-airport-entry]'))drawAirportSuggestions(event.target);});
  document.addEventListener('keydown',event=>{
    const input=event.target;if(!input.matches?.('input[data-airport-entry]'))return;
    const list=input.closest('.airport-field')?.querySelector('.airport-suggestions');
    if(event.key==='Escape'){closeAirportSuggestions();return;}
    if(!['ArrowDown','ArrowUp','Enter'].includes(event.key))return;
    if(!list||list.hidden){if(event.key!=='Enter'){drawAirportSuggestions(input);event.preventDefault();}return;}
    const options=Array.from(list.querySelectorAll('[data-airport-select]'));
    if(!options.length)return;
    const active=options.findIndex(x=>x.getAttribute('aria-selected')==='true');
    if(event.key==='Enter'){
      const pick=options[active]||(options.length===1?options[0]:null);
      if(pick){chooseAirport(input.dataset.input,pick.dataset.airportSelect);event.preventDefault();}return;
    }
    const next=event.key==='ArrowDown'?(active+1)%options.length:(active<0?options.length-1:(active-1+options.length)%options.length);
    options.forEach((x,i)=>x.setAttribute('aria-selected',String(i===next)));
    input.setAttribute('aria-activedescendant',options[next].id);event.preventDefault();
  });
  document.addEventListener('pointerdown',event=>{if(!event.target.closest?.('.airport-field'))closeAirportSuggestions();});
  const passengerTotal=()=>state.adults+state.children+state.infants;
  function paxPicker(){return `<div class="pax-wrap"><button type="button" class="search-field pax-field" data-action="toggle-pax" aria-expanded="${state.passengersOpen}"><span class="field-label">Travelers & class</span><span class="field-body">${ic('users',19)}<span>${passengerTotal()} ${passengerTotal()===1?'Traveler':'Travelers'}</span>${ic('chevron-down',16)}</span><span class="field-hint">${state.cabin}</span></button>${state.passengersOpen?`<div class="pax-popover"><h4>Travelers</h4>${[['Adults','adults','12+ years'],['Children','children','2–11 years'],['Infants','infants','Under 2 years']].map(([name,key,sub])=>`<div class="pax-row"><div><strong>${name}</strong><span>${sub}</span></div><div class="counter"><button type="button" aria-label="Remove ${name}" data-action="pax-minus" data-key="${key}" ${state[key] <= (key==='adults'?1:0)?'disabled':''}>${ic('minus',15)}</button><strong>${state[key]}</strong><button type="button" aria-label="Add ${name}" data-action="pax-plus" data-key="${key}" ${passengerTotal()>=9||key==='infants'&&state.infants>=state.adults?'disabled':''}>${ic('plus',15)}</button></div></div>`).join('')}<label class="cabin-label">Cabin class<select data-input="cabin"><option ${state.cabin==='Economy'?'selected':''}>Economy</option><option ${state.cabin==='Premium Economy'?'selected':''}>Premium Economy</option><option ${state.cabin==='Business'?'selected':''}>Business</option><option ${state.cabin==='First'?'selected':''}>First</option></select></label>${btn('Done','toggle-pax','btn btn-primary btn-block btn-sm')}</div>`:''}</div>`;}
  function searchWidget(){return `<div class="search-widget" id="flight-search"><div class="search-widget-top"><div class="search-tabs"><button type="button" class="search-tab ${state.tab==='flight'?'selected':''}" data-action="tab-flight">${ic('plane-small',19)} Flights</button><button type="button" class="search-tab ${state.tab==='hotel'?'selected':''}" data-action="tab-hotel">${ic('hotel',19)} Hotels</button></div><div class="widget-annotation">${ic('shield',15)} Compare available flight offers</div></div>${state.tab==='flight'?`<div class="widget-body"><div class="trip-row"><div class="trip-options">${[['round','Round trip'],['oneway','One way'],['multi','Multi-city']].map(([v,l])=>`<button type="button" data-action="trip-${v}" class="trip-option ${state.trip===v?'chosen':''}"><span class="radio-dot"></span>${l}</button>`).join('')}</div><span class="trip-note">${ic('info',16)} Real offers require a connected flight provider</span></div>${state.trip==='multi'?`<div class="multi-segments">${state.segments.map((s,i)=>`<div class="multi-segment"><span class="segment-title">Flight ${i+1}</span><div class="segment-grid">${airportField('From','from','plane-small',i)}${airportField('To','to','location',i)}${dateField('Departure','date',s.date,i)}${i>1?`<button class="remove-seg" data-action="remove-seg" data-index="${i}" aria-label="Remove flight">${ic('close',20)}</button>`:''}</div></div>`).join('')}</div><div class="multi-add">${btn(ic('plus',17)+' Add another flight','add-seg','btn btn-secondary btn-sm')}</div><div class="multi-footer">${paxPicker()}${btn('Explore flight plans '+ic('arrow-right',18),'search-flights','btn btn-primary btn-search')}</div>`:`<div class="flight-grid ${state.trip==='round'?'round-trip':'one-way'}">${airportField('From','from') }<button type="button" aria-label="Swap airports" class="swap-button" data-action="swap">${ic('swap',17)}</button>${airportField('To','to','location')}${dateField('Departure','departure',state.departure)}${state.trip==='round'?dateField('Return','returnDate',state.returnDate):''}${paxPicker()}${btn('Search flights '+ic('arrow-right',18),'search-flights','btn btn-primary btn-search')}</div>`}${state.error?`<div role="alert" class="form-error">${ic('info',18)} ${esc(state.error)}</div>`:''}</div>`:`<div class="widget-body"><div class="hotel-grid"><label class="search-field"><span class="field-label">Destination</span><span class="field-body">${ic('location',19)}<input data-input="hotelCity" value="${esc(state.hotelCity)}" placeholder="Where are you going?" /></span></label>${dateField('Check-in','checkin',state.checkin)}${dateField('Check-out','checkout',state.checkout)}<label class="search-field"><span class="field-label">Rooms & guests</span><span class="field-body">${ic('users',19)}<select data-input="hotelGuests">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${state.hotelGuests===n?'selected':''}>${n} ${n===1?'guest':'guests'}</option>`).join('')}</select></span></label>${btn('Plan your stay '+ic('arrow-right',18),'search-hotels','btn btn-primary btn-search')}</div>${state.error?`<div role="alert" class="form-error">${ic('info',18)} ${esc(state.error)}</div>`:''}<p class="hotel-note">${ic('info',15)} Hotel search is a frontend preview. Live reservations require a connected hotel provider.</p></div>`}</div>${airportList()}`;}
  function hero(){return `<section class="hero"><div class="hero-orbit orbit-one"></div><div class="hero-orbit orbit-two"></div><div class="hero-spark sparkle-a">✦</div><div class="hero-spark sparkle-b">✦</div><div class="container hero-inner"><div class="hero-copy"><div class="hero-eyebrow"><span class="pulse-dot"></span> YOUR JOURNEY STARTS HERE <span class="eyebrow-line"></span> THE WORLD AWAITS</div><h1>The world is waiting.<br/><span>Make every journey count.</span></h1><p>Discover routes, compare airlines, organize your travelers and create beautiful travel itineraries — all in one thoughtfully designed space.</p><div class="hero-badges"><span>${ic('check',16)} Smart route builder</span><span>${ic('check',16)} Downloadable travel itineraries</span><span>${ic('check',16)} Travel planning toolkit</span></div></div><div class="ef-hero-visual" aria-label="Animated flight-route illustration, not live flight tracking"><div class="ef-radar-head"><span class="ef-radar-pill"><span class="ef-radar-pulse"></span> ROUTE VISUALIZER</span><span class="ef-radar-meta">ANIMATED PREVIEW</span></div><div class="ef-map"><div class="ef-map-grid"></div><div class="ef-radar-ring ef-ring-one"></div><div class="ef-radar-ring ef-ring-two"></div><div class="ef-radar-sweep"></div><svg class="ef-route-svg" viewBox="0 0 460 256" aria-hidden="true" preserveAspectRatio="xMidYMid meet"><defs><linearGradient id="ef-path-gradient" x1="0" x2="1"><stop stop-color="#45e7cd"/><stop offset="1" stop-color="#82adff"/></linearGradient></defs><path class="ef-flight-trail" d="M76 183 Q205 11 387 73"/><path class="ef-flight-trail ef-trail-soft" d="M76 183 Q230 220 387 73"/><circle cx="76" cy="183" r="5" fill="#51edcf"/><circle cx="387" cy="73" r="5" fill="#82b7ff"/><circle cx="76" cy="183" r="13" fill="none" stroke="#51edcf" stroke-opacity=".5"/><circle cx="387" cy="73" r="13" fill="none" stroke="#82b7ff" stroke-opacity=".5"/><g class="ef-plane-moving"><path d="M0 -15 L4 -3 L16 2 L16 6 L4 5 L4 13 L9 16 L9 19 L0 16 L-9 19 L-9 16 L-4 13 L-4 5 L-16 6 L-16 2 L-4 -3 Z" fill="#ffffff" stroke="#5bead3" stroke-width="1.3"/></g></svg><div class="ef-map-location ef-location-a"><strong>DAC</strong><span>Dhaka</span></div><div class="ef-map-location ef-location-b"><strong>DXB</strong><span>Dubai</span></div><div class="ef-route-info"><span>EXPLORE NEW ROUTES</span><strong>Across continents</strong><small>Search actual offers with your connected provider</small></div></div><div class="ef-radar-foot"><span><i></i> One way</span><span><i></i> Round trip</span><span><i></i> Multi-city</span></div></div></div><div class="container hero-search">${searchWidget()}</div></section>`;}
  function airlinesStrip(){return `<section class="airlines-section"><div class="container"><div class="eyebrow centered">GLOBAL AIRLINE DIRECTORY</div><h2 class="airlines-heading">Explore the airlines that move the world.</h2><div class="airline-marquee"><div class="airline-track">${[...carriers,...carriers].map((a)=>`<span class="airline-chip">${airlineBadge(a)}<span>${esc(a)}</span></span>`).join('')}</div></div><p class="subnote">Actual airline brand logos are requested online; airline-code icons display only when unavailable. No airline partnership is implied.</p></div></section>`;}
  function steps(){const list=[['01','Search your route','Choose airports, dates, and how many people are traveling.','search'],['02','Explore options','Compare airline offers and choose a plan, if a flight provider is connected.','plane-small'],['03','Add traveler details','Enter names and review your itinerary information.','user'],['04','Save your plan','Print your clearly labeled travel plan as a PDF.','download']];return `<section class="section steps-section" id="how-it-works"><div class="container"><div class="section-heading center"><div class="eyebrow">THOUGHTFUL BY DESIGN</div><h2>From idea to itinerary, <em>in four easy steps.</em></h2><p>Everything you need to outline your journey, without unnecessary complexity.</p></div><div class="steps-grid">${list.map(([n,t,d,i],idx)=>`<div class="step-card"><div class="step-header"><div class="step-icon">${ic(i,23)}</div><span class="step-num">${n}</span></div><h3>${t}</h3><p>${d}</p>${idx!==3?`<span class="step-arrow">${ic('arrow-right',19)}</span>`:''}</div>`).join('')}</div></div></section>`;}
  function sampleTicket(isReal=false){return `<div class="ticket-visual"><div class="ticket-visual-head"><span class="mini-logo">${ic('plane-small',17)} biz-<span>flights</span></span><span class="ticket-tag">TRAVEL PLAN</span></div><div class="ticket-visual-title">Your upcoming journey <span class="ticket-bars">▏▏▏▏▏</span></div><div class="ticket-route"><div><b>DAC</b><small>Dhaka</small></div><div class="ticket-line"><div class="route-plane">${ic('plane-small',20)}</div><span>TRAVEL ITINERARY</span></div><div class="ticket-to"><b>DXB</b><small>Dubai</small></div></div><div class="ticket-meta"><div><small>DEPARTURE</small><strong>15 Nov 2026</strong></div><div><small>TRAVELER</small><strong>Alex Traveler</strong></div><div><small>CLASS</small><strong>Economy</strong></div></div><div class="ticket-bottom"><span>${ic('shield',16)} Planning document only</span><div class="bar-code"></div></div></div>`;}
  function featureSplit(){return `<section class="section feature-section"><div class="container feature-grid"><div class="feature-visual"><div class="feature-circle cir1"></div><div class="feature-circle cir2"></div>${sampleTicket()}<div class="floating-proof">${ic('check',18)} Your plan is ready to review</div></div><div class="feature-content"><div class="eyebrow">THE SMARTER WAY TO PLAN</div><h2>What is a <em>flight itinerary for a visa?</em></h2><p class="feature-intro">A flight itinerary outlines your proposed journey without purchasing an airline ticket. Biz-Flights lets you prepare a personal travel plan before you decide whether to book a flight.</p><div class="feature-list"><div><span>${ic('file',20)}</span><div><h3>Professional presentation</h3><p>Clean, printable itinerary layouts with your travel dates, cities and traveler details.</p></div></div><div><span>${ic('clock',20)}</span><div><h3>Easy, anytime planning</h3><p>Outline your route whenever you want — no waiting on an agency.</p></div></div><div><span>${ic('shield',20)}</span><div><h3>Transparent by default</h3><p>Draft itineraries are marked as travel plans, never misrepresented as booked flights.</p></div></div></div>${btn('Start planning '+ic('arrow-right',17),'start','btn btn-primary')}</div></div></section>`;}
  const accentClasses=['dest-blue','dest-teal','dest-orange','dest-purple','dest-rose','dest-green','dest-sky','dest-gold'];
  function destinationCards(codes=featuredCodes){return codes.map((code,i)=>{const a=airport(code);return `<button class="destination-card ${accentClasses[i%accentClasses.length]}" data-action="destination" data-code="${a.code}"><span class="dest-art">${ic('globe',70)}</span><span class="dest-top">POPULAR DESTINATION <span>${ic('arrow-right',18)}</span></span><span class="dest-content"><span class="dest-code">${a.code}</span><strong>${esc(a.city)}</strong><small>${esc(a.country)}</small><span class="dest-route">From Dhaka ${ic('arrow-right',14)} ${a.code}</span></span></button>`;}).join('');}
  function destinationsHome(){return `<section class="section destinations-section"><div class="container"><div class="section-heading heading-split"><div><div class="eyebrow">YOUR NEXT ADVENTURE</div><h2>Where will you <em>go next?</em></h2><p>Explore some of the most-loved routes from Bangladesh.</p></div><a href="#/destinations" class="text-link">All destinations ${ic('arrow-right',17)}</a></div><div class="destinations-grid">${destinationCards()}</div></div></section>`;}
  function benefits(){return `<section class="section confidence-section"><div class="container"><div class="confidence-band"><div class="confidence-intro"><div class="eyebrow eyebrow-light">FOR EVERY KIND OF TRAVELER</div><h2>Travel planning shouldn't feel complicated.</h2><p>Whether you're planning your first international trip or preparing travel information for clients, we make the steps easier to follow.</p>${btn('Explore our services '+ic('arrow-right',17),'individuals','btn btn-white')}</div><div class="confidence-items"><div>${ic('globe',25)}<div><strong>Global route ideas</strong><span>Explore popular cities around the world.</span></div></div><div>${ic('users',25)}<div><strong>Individual & group plans</strong><span>Add details for up to nine travelers.</span></div></div><div>${ic('building',25)}<div><strong>Agency-friendly workflow</strong><span>Organize frequent trip requests efficiently.</span></div></div></div></div></div></section>`;}
  const questions=[['Is this an actual airline ticket?','No. Biz-Flights currently creates travel-planning documents only. A draft itinerary is not an airline booking, a confirmed reservation, or an active PNR.'],['Can I download an itinerary as a PDF?','Yes. Yes. After entering traveler details, click “Download itinerary PDF” for a direct A4 download. You can also print from your browser. The PDF is clearly marked as an unconfirmed sample.'],['Are flight times and prices live?','Not in this frontend demo. Sample options are illustrative. For live schedule data and availability, connect a licensed flight inventory API.'],['Can I book hotels or pay by bKash?','Hotel reservations and bKash checkout are not connected in this demo. The interface provides the starting point for those integrations.'],['Can travel agencies use Biz-Flights?','The agency information page and sample plans are included. A production agency account and credit system requires backend authentication, billing, and administration.']];
  function faqs(){return `<section class="section faq-section"><div class="container faq-grid"><div class="faq-intro"><div class="eyebrow">GOOD TO KNOW</div><h2>Have questions?<br/><em>We have answers.</em></h2><p>A few things worth knowing before you plan your next journey.</p><a href="#/contact" class="text-link">Still need help? Contact us ${ic('arrow-right',17)}</a></div><div class="faq-items">${questions.map(([q,a],i)=>`<div class="faq-item ${state.faqOpen===i?'open':''}"><button class="faq-question" data-action="faq" data-index="${i}" aria-expanded="${state.faqOpen===i}">${q}${ic(state.faqOpen===i?'minus':'plus',18)}</button>${state.faqOpen===i?`<p>${a}</p>`:''}</div>`).join('')}</div></div></section>`;}
  function cta(){return `<section class="cta-section"><div class="container"><div class="cta-inner"><div class="cta-art">${ic('plane-small',69)}</div><div><div class="eyebrow eyebrow-light">LET'S GET MOVING</div><h2>Your next journey starts with a plan.</h2><p>Choose your destination and see how easy travel planning can be.</p></div>${btn('Explore flights '+ic('arrow-right',18),'start','btn btn-white btn-big')}</div></div></section>`;}
  function journeyShowcase(){return `<section class="ef-flight-showcase"><div class="container"><div class="ef-showcase-header"><div><span class="ef-showcase-kicker">A NEW WAY TO EXPLORE</span><h2>Every route, one seamless journey.</h2><p>Plan your flight from search to itinerary with a premium, intuitive travel experience.</p></div><span class="ef-preview-indicator"><span class="ef-radar-pulse"></span> Animated route examples</span></div><div class="ef-flight-scene"><div class="ef-scene-glow"></div><div class="ef-scene-line ef-scene-line-one"><span class="ef-scene-dot"></span></div><div class="ef-scene-line ef-scene-line-two"><span class="ef-scene-dot"></span></div><div class="ef-scene-airplane">✈</div><div class="ef-scene-from"><span>DEPART FROM</span><strong>Dhaka <small>DAC</small></strong></div><div class="ef-scene-to"><span>DISCOVER MORE</span><strong>Dubai <small>DXB</small></strong></div><div class="ef-scene-note">Illustrative flight route · Search for available offers above</div></div><div class="ef-showcase-features"><div><span>01</span><strong>Discover</strong><small>Search across available airline offers</small></div><div><span>02</span><strong>Compare</strong><small>Explore routes, stops and fares</small></div><div><span>03</span><strong>Prepare</strong><small>Add travel details and download itineraries</small></div></div></div></section>`;}
  // You2-Biz: only the search box; the marketing sections of the public site are not shown.
  function home(){return `<section class="you2-search"><div class="container">${searchWidget()}</div></section>`;}
  function services(){const items=[['plane-small','Flight itineraries','Compare routes, passengers and airline-style schedule examples.','start'],['hotel','Hotel planning','Align check-in and check-out dates with your journey.','start-hotel'],['file','Document center','Understand invoices, receipts, PNRs and booking requirements.','documents'],['users','Agency workspace','Discover team workflows and traveler-request tools.','agencies'],['shield','Visa checklist','Keep track of key documents before you submit.','tools'],['search','PNR verification','Learn how to verify a legitimate airline booking reference.','pnr']];return `<section class="section services-section" id="services"><div class="container"><div class="section-heading center"><div class="eyebrow">BIZ FLIGHTS SERVICES</div><h2>Everything your journey needs. <em>One beautiful place.</em></h2><p>Thoughtful planning tools for individuals, families and travel teams.</p></div><div class="service-grid">${items.map(([icon,title,desc,action],i)=>`<button type="button" class="service-card service-${i}" data-action="${action}"><span class="service-icon">${ic(icon,25)}</span><strong>${title}</strong><span>${desc}</span><i>${ic('arrow-right',18)}</i></button>`).join('')}</div></div></section>`;}
  const checklistItems=['Valid passport and matching traveler details','Completed visa application and appointment confirmation','Travel dates and itinerary match the application','Confirmed hotel reservation if required by the embassy','Travel insurance if required','Financial supporting documents','Invitation, employment or student documents if applicable','Review the latest official embassy checklist'];
  function tools(){const count=checklistItems.filter((_,i)=>state.checklist[i]).length;return pageIntro('FREE TRAVEL TOOLS','Little details. <em>Big peace of mind.</em>','Organize your visa checklist and your saved trip details. Nothing is sent to a server.')+`<section class="section tool-section"><div class="container tool-columns"><div class="tool-card"><div class="tool-head"><span class="tool-icon">${ic('shield',24)}</span><div><h2>Visa preparation checklist</h2><p>Personal planning guide · not an official embassy checklist</p></div></div><div class="check-progress"><div><strong>${count} / ${checklistItems.length}</strong><span>items complete</span></div><div class="check-meter"><span style="width:${count/checklistItems.length*100}%"></span></div></div><div class="check-list">${checklistItems.map((item,i)=>`<label class="check-item"><input type="checkbox" data-checklist="${i}" ${state.checklist[i]?'checked':''}/><span>${esc(item)}</span></label>`).join('')}</div><div class="tool-foot">${btn('Reset checklist','reset-checklist','btn btn-outline btn-sm')}<small>Your selections are saved only in this browser.</small></div></div><div class="tool-stack"><article class="mini-tool"><span>${ic('heart',24)}</span><h3>Saved flight routes</h3><p>Keep a short list of routes and travel dates — no passport or sensitive traveler data is stored.</p>${btn('View my saved trips','saved','btn btn-primary btn-sm')}</article><article class="mini-tool"><span>${ic('file',24)}</span><h3>Document guidance</h3><p>Know the difference between a draft itinerary, a real booking, a PNR and a payment receipt.</p>${btn('Explore documents','documents','btn btn-outline btn-sm')}</article><article class="mini-tool"><span>${ic('info',24)}</span><h3>Before you submit</h3><p>Visa requirements vary by country and personal circumstances. Always verify against the issuing embassy's official checklist.</p></article></div></div></section>`;}
  function saved(){return pageIntro('MY SHORTLIST','Your next trips, <em>all in one place.</em>','Saved origin, destination and dates remain on this browser only.')+`<section class="section"><div class="container saved-wrap"><div class="saved-toolbar"><h2>${state.savedTrips.length} saved ${state.savedTrips.length===1?'trip':'trips'}</h2>${btn('Search flights','start','btn btn-primary btn-sm')}</div>${state.savedTrips.length?state.savedTrips.map((x,i)=>`<article class="saved-route"><div class="saved-route-icon">${ic('plane-small',23)}</div><div><strong>${esc(x.from)} ${ic('arrow-right',16)} ${esc(x.to)}</strong><p>${esc(x.trip)} · ${esc(x.date)}${x.returnDate?' — '+esc(x.returnDate):''} · ${esc(x.cabin)}</p></div>${btn('Search again','use-saved','btn btn-outline btn-sm',`data-index="${i}"`)}${btn(ic('close',18),'remove-saved','btn btn-quiet btn-sm',`data-index="${i}" aria-label="Remove saved trip"`)}</article>`).join(''):`<div class="saved-empty">${ic('heart',40)}<h3>Your wishlist is ready for adventure</h3><p>Search for flights and select “Save this route” to keep it here.</p>${btn('Explore flights','start','btn btn-primary')}</div>`}</div></section>`;}
  function pnr(){return pageIntro('BOOKING STATUS','Know your <em>PNR from your plan.</em>','Understand what a real airline reservation looks like and how to verify one.')+`<section class="section"><div class="container two-col"><div><div class="eyebrow">REAL BOOKING VERIFICATION</div><h2>Check it with the airline.</h2><p class="body-copy">A Passenger Name Record (PNR) is created by an airline or an authorized reservation system. A demo reference generated by Biz-Flights is never a genuine airline locator.</p><div class="doc-guide-list"><div>${ic('check',18)} Open your airline's official Manage Booking page</div><div>${ic('check',18)} Enter the real airline PNR and passenger surname</div><div>${ic('check',18)} Verify route, passenger names and ticketing status</div><div>${ic('check',18)} Check any document's validity with its issuer</div></div>${btn('Plan my trip','start','btn btn-primary')}</div><div class="status-showcase"><div class="status-dot"></div><div class="eyebrow">SYSTEM STATUS</div><h3>Airline reservation connection</h3><strong>Not connected</strong><p>This frontend cannot issue or check airline PNRs or live seat availability. Integrate a licensed GDS, NDC, or consolidator API to enable it.</p></div></div></section>`;}
  function documents(){return pageIntro('TRAVEL DOCUMENTS','Beautifully organized. <em>Clearly explained.</em>','Understand your paperwork before you travel, with precise differences between demo documents and genuine bookings.')+`<section class="section"><div class="container docs-grid">${[['file','Travel plan PDF','Available in the website demo','A professional A4 itinerary with passenger names, route legs, sample flight information and a clear unconfirmed status.','start'],['credit','Invoice & money receipt','Real purchases only','A legitimate invoice or payment receipt must come from an actual paid transaction. This demo never fabricates payment records.','contact'],['shield','Airline PNR verification','Requires provider integration','A checkable PNR comes from a licensed airline booking platform or directly from the airline.','pnr'],['hotel','Hotel confirmations','Requires live provider integration','For a visa application, use a reservation confirmed by the property or booking platform.','start-hotel']].map(([icon,title,tag,body,action])=>`<article class="document-card"><span>${ic(icon,29)}</span><div class="eyebrow">${tag}</div><h3>${title}</h3><p>${body}</p>${btn('Explore '+ic('arrow-right',16),action,'btn btn-outline btn-sm')}</article>`).join('')}</div></section>`;}
  function pageIntro(kicker,title,desc,cls=''){return `<section class="page-hero ${cls}"><div class="container"><div class="eyebrow eyebrow-light">${kicker}</div><h1>${title}</h1><p>${desc}</p></div></section>`;}
  function individuals(){return pageIntro('FOR INDIVIDUAL TRAVELERS','Plan your trip, <em>without the guesswork.</em>','Four simple steps to organize a travel itinerary and keep your journey details together.')+steps()+`<section class="section"><div class="container two-col"><div><div class="eyebrow">START HERE</div><h2>Everything begins with a destination.</h2><p class="body-copy">Enter where you're leaving from and where you want to go. Compare illustrative plans, select your route, enter traveler information, and print a document for personal planning.</p><p class="body-copy">To produce actual airline reservations or embassy-verifiable booking confirmations, a real reservation service must be integrated.</p>${btn('Plan a flight '+ic('arrow-right',17),'start','btn btn-primary')}</div><div class="soft-panel">${sampleTicket()}</div></div></section>`+faqs()+cta();}
  function agencies(){return pageIntro('BIZ FLIGHTS FOR AGENCIES','A smarter workspace for <em>travel teams.</em>','Organize travelers, streamline planning requests and prepare for a more scalable booking workflow.')+`<section class="section"><div class="container"><div class="section-heading center"><div class="eyebrow">DESIGNED TO SCALE</div><h2>More organization. <em>Less repetition.</em></h2><p>Explore the agency workflow and example plans below.</p></div><div class="agency-features"><div>${ic('users',25)}<h3>Manage traveler requests</h3><p>Work with individual or group itinerary details in a clear planning flow.</p></div><div>${ic('file',25)}<h3>Consistent documents</h3><p>Create neat, clearly labeled travel plans with a repeatable format.</p></div><div>${ic('clock',25)}<h3>Save administrative time</h3><p>Reduce time spent re-entering trip details and preparing basic drafts.</p></div></div><div class="pricing-head"><div class="eyebrow">EXAMPLE PACKAGE STRUCTURE</div><h2>Simple plans for different needs.</h2><p>Illustrative pricing structure only. No packages are currently sold on this demo.</p></div><div class="pricing-grid"><article class="price-card"><span class="plan-tag">FOR OCCASIONAL PLANNING</span><h3>Starter</h3><p>Explore the essential itinerary planning workflow.</p><div class="price">Free <span>/ demo</span></div><ul><li>${ic('check',17)} Search sample routes</li><li>${ic('check',17)} Preview travel plans</li><li>${ic('check',17)} Print itinerary PDF</li></ul>${btn('Try it now','start','btn btn-outline btn-block')}</article><article class="price-card prominent"><span class="plan-tag">FOR GROWING TEAMS</span><h3>Agency</h3><p>Designed for teams that handle multiple clients.</p><div class="price">Custom <span>/ integration</span></div><ul><li>${ic('check',17)} Team access & permissions*</li><li>${ic('check',17)} Centralized planning dashboard*</li><li>${ic('check',17)} Integration with flight providers*</li></ul>${btn('Discuss integration','contact','btn btn-primary btn-block')}<small>*Requires backend development; not currently enabled.</small></article></div></div></section>`+cta();}
  function destinations(){const q=state.destinationQuery.trim().toLowerCase();const filtered=airports.filter(a=>a.code!=='DAC'&&a.code!=='CGP'&&a.code!=='ZYL'&&(`${a.city} ${a.code} ${a.country}`.toLowerCase().includes(q)));return pageIntro('DESTINATIONS','Your next destination <em>is waiting.</em>','Explore international routes from Dhaka and choose where your travel plan begins.')+`<section class="section destinations-page"><div class="container"><div class="destination-toolbar"><div><h2>Explore ${filtered.length} destinations</h2><p>Pick a city to fill in your flight search automatically.</p></div><label class="dest-search">${ic('search',19)}<input placeholder="Search city, airport or country" data-input="destinationQuery" value="${esc(state.destinationQuery)}" /></label></div><div class="destinations-grid">${destinationCards(filtered.map(a=>a.code))}</div>${filtered.length?'':`<div class="empty-state">${ic('search',35)}<h3>No destinations found</h3><p>Try a different city or airport code.</p></div>`}</div></section>`+cta();}
  const guideItems=[['TRAVEL BASICS','What is a flight itinerary for visa applications?','Learn the difference between your proposed travel plan, an airline hold, and a confirmed ticket.'],['HOW-TO','How to organize a trip itinerary','Pick your dates, destinations and travelers, then keep all your travel details in one place.'],['SMART PLANNING','Five things to check before applying','Review passport spelling, travel dates, official embassy checklist, insurance and accommodation information.'],['FLIGHT BOOKINGS','What is a PNR and how does it work?','A real PNR is created by an airline booking system and must be verifiable with the airline.'],['HOTELS','Planning accommodation for a visa','Understand when a real hotel reservation may be required and why supporting documents must be accurate.'],['FOR AGENCIES','Keeping client travel plans organized','Simple ways to standardize planning and reduce mistakes when working on multiple itineraries.']];
  function guides(){return pageIntro('TRAVEL KNOW-HOW','A little knowledge goes <em>a long way.</em>','Helpful information for planning your trip and understanding travel documents.')+`<section class="section"><div class="container"><div class="guides-grid">${guideItems.map(([k,t,d],i)=>`<article class="guide-card"><div class="guide-graphic guide-graphic-${i%3}">${ic(i%3===0?'globe':i%3===1?'file':'plane-small',45)}</div><div class="guide-card-body"><div class="eyebrow">${k}</div><h3>${t}</h3><p>${d}</p><a href="#/contact" class="text-link">Ask a question ${ic('arrow-right',16)}</a></div></article>`).join('')}</div></div></section>`+cta();}
  function about(){return pageIntro('ABOUT BIZ FLIGHTS','Built around the <em>joy of going places.</em>','We believe preparing for a journey should be clear, welcoming and straightforward.')+`<section class="section"><div class="container two-col"><div><div class="eyebrow">OUR IDEA</div><h2>Travel starts long before takeoff.</h2><p class="body-copy">Biz-Flights is a travel planning experience built to simplify the earliest steps of a journey. Our goal is to make it easy to organize route options, dates and passenger information in one place.</p><p class="body-copy">This release is a frontend demonstration. It does not make live bookings or issue airline-confirmed documents, and we don't claim a partnership with any named airline.</p>${btn('Explore destinations '+ic('arrow-right',17),'destinations','btn btn-primary')}</div><div class="about-feature">${ic('globe',95)}<div>It begins with a place.<br/><em>It becomes a journey.</em></div></div></div></section>`+cta();}
  function contact(){return pageIntro('GET IN TOUCH',"We're here to <em>help you plan.</em>",'Have a question about travel planning or want to integrate real booking services? Send your inquiry.')+`<section class="section"><div class="container contact-grid"><div class="contact-info"><div class="eyebrow">LET'S CONNECT</div><h2>Tell us what you're building.</h2><p>Share your name, email and message. This demo prepares your inquiry for copying; no details are sent to a server.</p><div class="contact-info-card">${ic('mail',24)}<div><strong>Get in touch</strong><span>Use the contact form to draft an inquiry.</span></div></div><div class="contact-info-card">${ic('globe',24)}<div><strong>Worldwide planning</strong><span>Designed for travelers in Bangladesh and beyond.</span></div></div></div><form id="contact-form" class="contact-form"><h3>Send a message</h3><label>Your name<input name="name" required placeholder="Your full name" autocomplete="name" /></label><label>Email address<input name="email" type="email" required placeholder="you@example.com" autocomplete="email" /></label><label>What can we help with?<select name="topic"><option>General inquiry</option><option>Flight data integration</option><option>Agency access</option><option>Payment integration</option></select></label><label>Your message<textarea name="message" rows="5" required placeholder="Tell us a little about your request..."></textarea></label><button class="btn btn-primary btn-block" type="submit">${ic('file',18)} Copy inquiry to clipboard</button><p class="form-hint" role="status">${esc(state.contactFeedback||'Demo only — messages are not submitted or stored online.')}</p></form></div></section>`;}
  function journeyLegs(){if(!state.search)return [];const s=state.search;return s.trip==='multi'?s.segments.map(x=>({...x})):s.trip==='round'?[{from:s.from,to:s.to,date:s.departure},{from:s.to,to:s.from,date:s.returnDate}]:[{from:s.from,to:s.to,date:s.departure}];}
  function demoTime(i,legIndex){const list=[['09:15','16:25'],['02:40','10:05'],['19:30','05:45 +1']];return list[(i+legIndex)%list.length];}
  function resultOptions(){return [
    {name:'Smart connection',carrier:'Qatar Airways',via:'1 stop · Doha',viaCode:'DOH',carrierCode:'QR',i:0,shade:'plum',duration:'15h 15m',price:82450,flightNumbers:['QR 641','QR 007','QR 008','QR 640'],aircraft:['Boeing 787-8','Airbus A350-1000'],baggage:'25 kg'},
    {name:'Flexible departure',carrier:'Emirates',via:'1 stop · Dubai',viaCode:'DXB',carrierCode:'EK',i:1,shade:'red',duration:'15h 40m',price:89500,flightNumbers:['EK 585','EK 003','EK 004','EK 584'],aircraft:['Boeing 777-300ER','Airbus A380-800'],baggage:'30 kg'},
    {name:'Great connection',carrier:'Turkish Airlines',via:'1 stop · Istanbul',viaCode:'IST',carrierCode:'TK',i:2,shade:'crimson',duration:'16h 20m',price:78600,flightNumbers:['TK 713','TK 1981','TK 1982','TK 712'],aircraft:['Airbus A330-300','Boeing 777-300ER'],baggage:'23 kg'}
  ];}
  const money=n=>'৳'+Number(n).toLocaleString('en-BD');
  const shortDate=s=>new Date(s+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});
  // One fixed stock of 1,000 internal six-digit itinerary references.
  // A hash selects a stock entry: the same itinerary gets the same reference,
  // while unrelated itineraries may reuse a code. These are NOT airline PNRs.
  const internalReferences = Object.freeze(Array.from({length:1000}, (_,i) =>
    String((100003 + i * 7919) % 1000000).padStart(6, '0')));
  const sampleRef=()=>{
    const seed=[state.search?.departure||'',state.search?.from||'',state.search?.to||'',state.search?.returnDate||'',
      state.selected??0,...state.travellers.map(t=>`${t.first||''}|${t.last||''}|${t.dob||''}`)].join('|');
    let hash=2166136261;
    for(let i=0;i<seed.length;i++)hash=Math.imul(hash^seed.charCodeAt(i),16777619)>>>0;
    return internalReferences[hash % internalReferences.length];
  };
  function sampleSectors(leg,option,legIndex){
    // Flight numbers, schedules and aircraft below are visual DEMONSTRATION DATA, not retrieved from live inventory.
    const middle=option.viaCode;const nodes=(leg.from===middle||leg.to===middle)?[leg.from,leg.to]:[leg.from,middle,leg.to];
    const returning=legIndex>0;const times=returning?[["15:10","00:35"],["02:15","09:25"]]:[["03:55","06:10"],["08:35","13:20"]];
    if(option.i===1){times[0]=returning?['14:10','00:55']:['09:55','13:15'];times[1]=returning?['03:40','10:00']:['15:20','19:15'];}
    if(option.i===2){times[0]=returning?['16:05','23:45']:['06:20','12:15'];times[1]=returning?['02:10','13:25']:['14:10','16:15'];}
    const dates=returning?[leg.date,addDays(1,leg.date)]:[leg.date,leg.date];
    return nodes.slice(0,-1).map((from,j)=>{
      let fromCode=from,toCode=nodes[j+1];const t=nodes.length===2?times[0]:times[j];
      const departDate=dates[j]||leg.date;
      const overnight=returning&&j===0;
      return {from:airport(fromCode),to:airport(toCode),date:shortDate(departDate),isoDate:departDate,
        arrivalDate:shortDate(overnight?addDays(1,departDate):departDate),departureTime:t[0],arrivalTime:t[1],
        flightNo:option.flightNumbers[(legIndex%2)*2+j]||`${option.carrierCode} ---`, aircraft:option.aircraft[j%2],
        terminalFrom:'Check with airline',terminalTo:'Check with airline',baggage:option.baggage, cabin:state.search.cabin,
        duration:j===0?'5h 30m':'7h 05m',segmentIndex:j+1,segmentTotal:nodes.length-1,routeIndex:legIndex+1};
    });
  }
  function searchSummary(){const legs=journeyLegs();return `<div class="results-summary"><div class="results-route-icon">${ic('plane-small',24)}</div><div><strong>${legs.length===1?`${esc(airport(legs[0].from).city)} to ${esc(airport(legs[0].to).city)}`:`${esc(airport(legs[0].from).city)} to ${esc(airport(legs[0].to).city)} ${state.search.trip==='round'?'— return trip':`— ${legs.length} flights`}`}</strong><span>${legs.map(l=>fmtDate(l.date)).join(' · ')} · ${state.search.adults+state.search.children+state.search.infants} traveler(s) · ${esc(state.search.cabin)}</span></div><div class="summary-actions">${btn('Edit search','start','btn btn-outline btn-sm')}</div></div>`;}
  function routeLine(leg,option,index){
    const segs=sampleSectors(leg,option,index),first=segs[0],last=segs[segs.length-1];
    return `<div class="result-leg flight-result-leg"><div class="leg-station"><strong>${first.departureTime}</strong><span>${esc(first.from.code)} · ${esc(first.from.city)}</span><small>${esc(first.date)}</small></div><div class="leg-journey"><span>${ic('plane-small',15)} ${segs.length===2?'1 stop in '+esc(airport(option.viaCode).city):'Sample nonstop'}</span><div class="leg-divider"><span></span>${ic('plane-small',19)}<span></span></div><small>${esc(option.duration)} · ${esc(state.search.cabin)}</small></div><div class="leg-station to"><strong>${last.arrivalTime}</strong><span>${esc(last.to.code)} · ${esc(last.to.city)}</span><small>${esc(last.arrivalDate)}</small></div></div>`;
  }
  function visibleOptions(){let options=[...resultOptions()];if(state.routeFilter!=='all')options=options.filter(x=>x.carrierCode===state.routeFilter);if(state.sortBy==='cheapest')options.sort((a,b)=>a.price-b.price);else if(state.sortBy==='duration')options.sort((a,b)=>parseInt(a.duration)-parseInt(b.duration));else options.sort((a,b)=>b.price-a.price);return options;}

  // Flight offers come from the server; never silently substitute demo schedules.
  const liveMoney=o=>`${esc(o.currency||'')} ${Number(o.amount||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
  const liveTime=v=>v?String(v).slice(11,16):'—';
  const liveDate=v=>v?fmtDate(String(v).slice(0,10)):'—';
  const firstSegment=o=>o?.slices?.[0]?.segments?.[0]||{};
  const mainCarrier=o=>firstSegment(o).operatingAirline||firstSegment(o).marketingAirline||'Airline';
  const mainCarrierCode=o=>firstSegment(o).operatingCode||firstSegment(o).marketingCode||'EF';
  const offerStopCount=o=>(o.slices||[]).reduce((n,sl)=>n+Math.max(0,(sl.segments||[]).length-1),0);
  function providerAirlines(o){return [...new Set((o.slices||[]).flatMap(sl=>sl.segments||[]).map(seg=>seg.operatingAirline||seg.marketingAirline).filter(Boolean))]}
  function sortLive(items){let arr=[...items];if(state.routeFilter!=='all')arr=arr.filter(o=>(o.slices||[]).some(sl=>(sl.segments||[]).some(seg=>seg.operatingCode===state.routeFilter||seg.marketingCode===state.routeFilter)));
    if(state.liveStopFilter==='direct')arr=arr.filter(o=>offerStopCount(o)===0);if(state.liveStopFilter==='one')arr=arr.filter(o=>offerStopCount(o)<=1);
    if(state.sortBy==='cheapest')arr.sort((a,b)=>Number(a.amount)-Number(b.amount));else if(state.sortBy==='premium')arr.sort((a,b)=>Number(b.amount)-Number(a.amount));else arr.sort((a,b)=>parseInt(a.slices?.[0]?.duration||999)-parseInt(b.slices?.[0]?.duration||999));return arr;
  }
  async function doLiveSearch(){const q=state.search;if(!q)return;state.usingDemo=false;state.live={status:'loading',offers:[],after:null,requestId:null,visibleLimit:12,loadingMore:false,error:'',liveMode:false};render();
    try{const r=await fetch(window.AIR_TICKET.api+'flights/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({legs:q.segments,adults:q.adults,children:q.children,infants:q.infants,cabin:q.cabin})});let d;try{d=await r.json()}catch{throw Error('Live flight API unavailable. Upload this website to Node.js hosting and start server.js.')}if(!r.ok)throw Error(d.error||'Flight provider search failed.');
      state.live={status:'ready',offers:d.offers||[],after:d.after,requestId:d.requestId,visibleLimit:12,loadingMore:false,error:'',liveMode:d.liveMode,source:d.source,searchedAt:d.searchedAt};render();
    }catch(e){state.live={status:'error',offers:[],after:null,requestId:null,error:e.message||'Unable to connect to flight provider.',visibleLimit:12,loadingMore:false};render();}
  }
  async function loadMoreFlights(all=false){const q=state.live;if(!q?.after||q.loadingMore)return;q.loadingMore=true;q.error='';render();let count=0;
    try{do{const params=new URLSearchParams({requestId:q.requestId,after:q.after});const r=await fetch(window.AIR_TICKET.api+'flights/more&'+params);const d=await r.json();if(!r.ok)throw Error(d.error||'Could not load the next page');q.offers.push(...(d.offers||[]));q.after=d.after;count++;q.visibleLimit=all?Math.max(q.visibleLimit,q.offers.length):Math.min(q.offers.length,q.visibleLimit+12);if(all&&count%3===0){q.loadingMore=true;render();}}while(all&&q.after&&count<40);q.loadingMore=false;render();}catch(e){q.error=e.message;q.loadingMore=false;render();}
  }
  function liveSliceLine(slice,index){const segs=slice?.segments||[],first=segs[0],last=segs[segs.length-1];if(!first)return '';
    const stops=segs.length-1,stopText=stops===0?'Nonstop':`${stops} stop${stops===1?'':'s'} · ${segs.slice(0,-1).map(s=>s.destination?.code).join(', ')}`;
    return `<div class="result-leg flight-result-leg"><div class="leg-station"><strong>${liveTime(first.departingAt)}</strong><span>${esc(first.origin.code)} · ${esc(first.origin.city||first.origin.name)}</span><small>${liveDate(first.departingAt)}</small></div><div class="leg-journey"><span>${ic('plane-small',15)} ${esc(stopText)}</span><div class="leg-divider"><span></span>${ic('plane-small',19)}<span></span></div><small>${esc(slice.duration||'')} · local times</small></div><div class="leg-station to"><strong>${liveTime(last.arrivingAt)}</strong><span>${esc(last.destination.code)} · ${esc(last.destination.city||last.destination.name)}</span><small>${liveDate(last.arrivingAt)}</small></div></div>
    <div class="live-segment-info">${segs.map(s=>`<span>${esc(s.operatingAirline||s.marketingAirline)} ${esc(s.flightNumber)} · ${esc(s.origin.code)} → ${esc(s.destination.code)}</span>`).join('')}</div>`;
  }
  function liveResults(){const q=state.live,found=sortLive(q.offers),visible=found.slice(0,q.visibleLimit),codes=[...new Map(q.offers.flatMap(o=>(o.slices||[]).flatMap(sl=>(sl.segments||[]).map(g=>[g.operatingCode||g.marketingCode,g.operatingAirline||g.marketingAirline]))).filter(([c])=>c)).entries()].sort((a,b)=>a[1].localeCompare(b[1]));
    const empty=q.status==='loading'?`<div class="live-state"><div class="ef-spinner"></div><h2>Searching airline inventory…</h2><p>Contacting airlines through the connected provider. Your results will show real offer details.</p></div>`:q.status==='error'?`<div class="live-state live-state-error">${ic('info',31)}<h2>Live flight results unavailable</h2><p>${esc(q.error)}</p><p>No sample flights are presented as live results.</p>${btn('Try again','retry-live','btn btn-primary btn-sm')} ${btn('Open separate demo preview','demo-flights','btn btn-secondary btn-sm')}</div>`:`<div class="live-state">${ic('search',30)}<h2>No matching offers ${q.offers.length?'with these filters':'for this search'}</h2><p>${q.offers.length?'Try another airline or remove the stop filter.':'Try nearby airports or different dates. Provider coverage varies by route.'}</p>${q.offers.length?btn('Clear filters','clear-live-filters','btn btn-secondary btn-sm'):btn('Change your search','start','btn btn-primary btn-sm')}</div>`;
    return `<section class="results-header"><div class="container"><div class="eyebrow eyebrow-light">BIZ FLIGHTS · CONNECTED FLIGHT INVENTORY</div><h1>Find your next flight.</h1><p>Airline schedules, stops, and offer prices returned by the provider — not hand-entered sample flights.</p></div></section><section class="results-main"><div class="container">${searchSummary()}<div class="results-layout"><aside class="filter-side"><div class="filter-title">${ic('search',19)} Live search</div><div class="filter-row">${ic('plane-small',16)} ${esc(state.search.from)} → ${esc(state.search.to)}</div><div class="filter-row">${ic('calendar',16)} ${fmtDate(state.search.departure)}</div><div class="filter-row">${ic('users',16)} ${state.search.adults+state.search.children+state.search.infants} traveler(s)</div><div class="filter-divider"></div><h3>How availability works</h3><div class="filter-row">${ic('check',17)} Multiple airlines and connections</div><div class="filter-row">${ic('check',17)} Refresh offer before selection</div></aside><div class="results-list"><div class="results-list-title"><div><h2>${q.status==='loading'?'Searching airlines…':'Flight search results'}</h2><p>${q.status==='ready'?`${q.offers.length} flight offers loaded · Prices in provider currency`:'Provider connection required for authentic schedules'}</p></div><span class="${q.liveMode?'live-pill':'demo-pill'}">${q.status==='loading'?'SEARCHING':q.status==='error'?'NOT CONNECTED':q.liveMode?'LIVE OFFERS':'TEST DATA'}</span></div>
    ${q.status==='ready'?`<div class="result-controls"><label>Airline <select data-input="routeFilter"><option value="all" ${state.routeFilter==='all'?'selected':''}>All airlines</option>${codes.map(([c,n])=>`<option value="${esc(c)}" ${state.routeFilter===c?'selected':''}>${esc(n)}</option>`).join('')}</select></label><label>Stops <select data-input="liveStopFilter"><option value="all" ${state.liveStopFilter==='all'?'selected':''}>All</option><option value="direct" ${state.liveStopFilter==='direct'?'selected':''}>Nonstop only</option><option value="one" ${state.liveStopFilter==='one'?'selected':''}>Max 1 stop total</option></select></label><label>Sort <select data-input="sortBy"><option value="cheapest" ${state.sortBy==='cheapest'?'selected':''}>Lowest fare</option><option value="duration" ${state.sortBy==='duration'?'selected':''}>Shortest</option><option value="premium" ${state.sortBy==='premium'?'selected':''}>Highest fare</option></select></label><span>${visible.length} shown / ${found.length} matching loaded</span></div>`:''}
    ${visible.map(o=>{const i=q.offers.indexOf(o);const names=providerAirlines(o);const stops=offerStopCount(o);return `<article class="result-card booking-result-card live-flight-card"><div class="result-top">${airlineBadge(mainCarrier(o),mainCarrierCode(o),'airline-result-badge')}<div><strong>${esc(mainCarrier(o))}</strong><span>Operated by ${esc(names.join(', ')||mainCarrier(o))} · ${o.slices.length} journey${o.slices.length!==1?'s':''} · ${stops} connection${stops===1?'':'s'}</span></div><span class="live-fare-tag">${q.liveMode?'AIRLINE OFFER':'PROVIDER TEST'}</span></div><div class="result-legs">${o.slices.map(liveSliceLine).join('')}</div><div class="booking-result-foot"><div class="booking-fare"><small>Provider total · ${state.search.adults+state.search.children+state.search.infants} traveler(s)</small><strong>${liveMoney(o)}</strong><span>${o.expiresAt?'Offer expires '+esc(new Date(o.expiresAt).toLocaleString('en-GB')):'Price subject to recheck'}</span></div><div class="booking-amenities"><span>${ic('check',14)} ${esc(state.search.cabin)}</span><span>${ic('check',14)} ${stops?'Connecting':'Nonstop'}</span></div>${q.checkingOffer===i?`<button type="button" class="btn btn-primary is-checking" disabled aria-busy="true"><span class="btn-spinner" aria-hidden="true"></span> Checking latest price…</button>`:btn('Review live offer '+ic('arrow-right',17),'select-live-offer','btn btn-primary',`data-plan="${i}"${q.checkingOffer!=null?' disabled':''}`)}</div>${q.offerError&&q.offerError.i===i?`<div role="alert" class="form-error offer-error">${esc(q.offerError.msg)}</div>`:''}</article>`}).join('')}
    ${!visible.length?empty:''}${q.status==='ready'&&found.length>visible.length?`<div class="load-more-panel">${btn(`Show 12 more`,'show-more-local','btn btn-secondary')}</div>`:''}${q.error&&q.status==='ready'?`<div role="alert" class="form-error">${esc(q.error)}</div>`:''}
    ${q.status==='ready'?`<p class="inventory-disclaimer">${ic('info',17)} ${q.liveMode?'Real supplier offers; prices and seat availability may change until booking.':'Provider test environment: data is NOT current live airline availability.'} Airline PNR and e-ticket numbers are not issued by this website. ${q.after?'Load additional pages to see more results.':''}</p>`:''}
    </div></div></div></section>`;
  }
  async function selectLiveOffer(i){const q=state.live,offer=q?.offers[i];if(!offer||q.checkingOffer!=null)return;q.error='';q.offerError=null;q.checkingOffer=i;render();try{const params=new URLSearchParams({requestId:q.requestId,id:offer.id});const r=await fetch(window.AIR_TICKET.api+'flights/offer&'+params);const d=await r.json();if(!r.ok)throw Error(d.error||'Unable to recheck offer.');q.offers[i]=d.offer;state.selected=i;q.checkingOffer=null;navigate('travellers');}catch(e){q.checkingOffer=null;q.offerError={i,msg:(e.message||'Unable to recheck offer.')+' Please try again or choose another offer.'};render();}}
  function results(){if(state.live)return liveResults();if(!state.search)return pageIntro('FLIGHT SEARCH',"Let's find your <em>travel plan.</em>",'Start by choosing a destination and travel dates.')+`<div class="container section">${btn('Start searching','start','btn btn-primary')}</div>`;
    return `<section class="results-header"><div class="container"><div class="eyebrow eyebrow-light">FLIGHT SEARCH · BIZ FLIGHTS</div><h1>Choose your flights.</h1><p>Compare airline-style travel options for your selected route.</p></div></section><section class="results-main"><div class="container">${searchSummary()}<div class="results-layout"><aside class="filter-side"><div class="filter-title">${ic('sliders-horizontal',20)} Refine your journey</div><h3>Your journey</h3><div class="filter-row">${ic('plane-small',18)} ${esc(state.search.from)} to ${esc(state.search.to)}</div><div class="filter-row">${ic('calendar',18)} ${fmtDate(state.search.departure)}</div><div class="filter-row">${ic('users',18)} ${state.search.adults+state.search.children+state.search.infants} traveler(s)</div><div class="filter-divider"></div><h3>Included in your preview</h3><div class="filter-row">${ic('check',17)} Route and connection details</div><div class="filter-row">${ic('check',17)} Airline-style trip summary</div><div class="filter-row">${ic('check',17)} PDF itinerary download</div><div class="filter-divider"></div><div class="booking-note">${ic('info',17)} <span>These options use demo flight numbers, fares and times. No seats are held or booked.</span></div></aside><div class="results-list"><div class="results-list-title"><div><h2>Available-style flight options</h2><p>${resultOptions().length} example itineraries · sorted by illustrative fares</p></div><span class="demo-pill">DEMO FLIGHTS</span></div><div class="result-controls"><label>Airline <select data-input="routeFilter"><option value="all" ${state.routeFilter==='all'?'selected':''}>All airlines</option>${resultOptions().map(o=>`<option value="${o.carrierCode}" ${state.routeFilter===o.carrierCode?'selected':''}>${o.carrier}</option>`).join('')}</select></label><label>Sort by <select data-input="sortBy"><option value="cheapest" ${state.sortBy==='cheapest'?'selected':''}>Lowest sample fare</option><option value="duration" ${state.sortBy==='duration'?'selected':''}>Shortest sample duration</option><option value="premium" ${state.sortBy==='premium'?'selected':''}>Highest sample fare</option></select></label><span>${visibleOptions().length} results</span></div>${visibleOptions().map(o=>`<article class="result-card booking-result-card"><div class="result-top">${airlineBadge(o.carrier,o.carrierCode,'airline-result-badge')}<div><strong>${esc(o.carrier)}</strong><span>${esc(o.name)} · ${esc(o.via)}</span></div><span class="fare-label">Sample schedule</span></div><div class="result-legs">${journeyLegs().map((leg,k)=>routeLine(leg,o,k)).join('')}</div><div class="booking-result-foot"><div class="booking-fare"><small>Illustrative total / traveler</small><strong>${money(o.price)}</strong><span>Not a live fare · No payment required</span></div><div class="booking-amenities"><span>${ic('check',14)} ${esc(o.baggage)} baggage</span><span>${ic('check',14)} ${esc(state.search.cabin)}</span></div>${btn(state.compare.includes(o.i)?'✓ Added to compare':ic('plus',16)+' Compare','compare-plan','btn btn-outline btn-sm',`data-plan="${o.i}"`)}${btn('View itinerary '+ic('arrow-right',17),'select-plan','btn btn-primary',`data-plan="${o.i}"`)}</div></article>`).join('')}${state.compare.length?`<div class="compare-panel"><div><strong>${state.compare.length} flight ${state.compare.length===1?'option':'options'} selected</strong><p>Compare illustrative sample fares and baggage at a glance.</p></div>${btn('Show comparison','show-compare','btn btn-primary btn-sm')}${btn(ic('close',18),'clear-compare','btn btn-quiet btn-sm')}</div>`:''}<p class="inventory-disclaimer">${ic('info',17)} Airline names and example flight numbers are for visual demonstration. Confirm flights, availability, price and terminal details with an airline or booking provider.</p></div></div></div></section>`;
  }
  function progress(n){return `<div class="checkout-progress">${[['01','Choose route'],['02','Traveler details'],['03','Review itinerary']].map(([num,t],i)=>`<div class="progress-step ${i+1<=n?'complete':''} ${i+1===n?'current':''}"><span>${i+1<n?ic('check',15):num}</span>${t}</div>${i!==2?`<div class="progress-connector ${i+1<n?'complete':''}"></div>`:''}`).join('')}</div>`;}
  const natOptions=['Bangladeshi','Indian','Malaysian','British','American','Canadian','Australian','Other'];
  function travellerFields(p,i){
    const scan=state.passportScan[i]||{};
    const extra=p.nationality&&!natOptions.includes(p.nationality)?[p.nationality]:[];
    const isBusy=scan.status==='scanning';
    const notice=scan.message?`<div class="passport-scan-status ${scan.status==='success'?'scan-success':scan.status==='error'?'scan-error':'scan-progress'}" role="status" aria-live="polite">${isBusy?'<span class="passport-spinner" aria-hidden="true"></span>':ic(scan.status==='success'?'check':'info',16)}<span>${esc(scan.message)}</span></div>`:'';
    return `<div class="traveler-panel" data-passport-panel="${i}"><div class="traveler-number"><span>${ic('user',20)} Traveler ${i+1}</span><small>${i<state.search.adults?'Adult':i<state.search.adults+state.search.children?'Child':'Infant'}</small></div>
    <div class="passport-scan-panel"><div class="passport-scan-badge">${ic('file',21)}</div><div class="passport-scan-content"><strong>Autofill from passport photo</strong><p>Upload a clear image of the passport information page. Include the two machine-readable lines at the bottom.</p><div class="passport-scan-actions"><label class="passport-upload-button ${isBusy?'is-busy':''}" for="passport-photo-${i}">${ic('file',17)} ${isBusy?'Reading passport…':'Upload passport photo'}<input id="passport-photo-${i}" type="file" accept="image/*" data-passport-photo="${i}" aria-label="Upload passport photo for traveler ${i+1}" ${isBusy?'disabled':''}/></label><span>JPG / PNG · Max 15 MB</span></div>${notice}<small class="passport-privacy">${ic('shield',13)} Your image is processed in this browser and is not uploaded to Biz-Flights. Please verify all extracted details.</small></div></div>
    <div class="traveler-grid"><label>First / given name<input data-traveller="${i}" data-field="first" value="${esc(p.first||'')}" placeholder="As on passport" required autocomplete="off" /></label><label>Last / family name<input data-traveller="${i}" data-field="last" value="${esc(p.last||'')}" placeholder="As on passport" required autocomplete="off" /></label><label>Date of birth <span class="optional">(optional)</span><input type="date" data-traveller="${i}" data-field="dob" value="${esc(p.dob||'')}" max="${today()}" /></label><label>Nationality <span class="optional">(optional)</span><select data-traveller="${i}" data-field="nationality"><option value="">Select nationality</option>${[...natOptions,...extra].map(x=>`<option value="${esc(x)}" ${p.nationality===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Passport number <span class="optional">(optional)</span><input data-traveller="${i}" data-field="passport" value="${esc(p.passport||'')}" placeholder="Passport number" autocomplete="off" /></label><label>Passport expiry <span class="optional">(optional)</span><input type="date" data-traveller="${i}" data-field="passportExpiry" value="${esc(p.passportExpiry||'')}" /></label><label>Gender <span class="optional">(optional)</span><select data-traveller="${i}" data-field="gender"><option value="">Select gender</option>${['Male','Female','Unspecified'].map(x=>`<option value="${x}" ${p.gender===x?'selected':''}>${x}</option>`).join('')}</select></label></div></div>`;
  }
  const scanNonce={};
  async function scanPassportPhoto(index,file){
    if(!Number.isInteger(index)||index<0||index>=state.travellers.length)return;
    const nonce=(scanNonce[index]||0)+1;scanNonce[index]=nonce;
    state.passportScan[index]={status:'scanning',message:'Preparing image…'};render();
    try{
      if(!window.ExplorePassportOCR)throw new Error('Passport scanner script did not load. Please refresh the page.');
      const fields=await window.ExplorePassportOCR.recognize(file,message=>{
        if(scanNonce[index]!==nonce||state.view!=='travellers')return;
        state.passportScan[index]={status:'scanning',message};
        const node=document.querySelector(`[data-passport-panel="${index}"] .passport-scan-status span:last-child`);
        if(node)node.textContent=message;
      });
      if(scanNonce[index]!==nonce||state.view!=='travellers')return;
      const dest=state.travellers[index]||{};
      // Non-empty extracted fields only. Dates and passport number are filled only after valid check digits.
      let updated=0;
      for(const key of ['first','last','dob','nationality','passport','passportExpiry','gender']){
        if(fields[key]){dest[key]=fields[key];updated++;}
      }
      state.travellers[index]=dest;
      const verified=fields.validated;
      const attention=(verified<3?' Some MRZ check digits did not pass; verify missing fields manually.':'')
        +(fields.nameNeedsReview?' The name could not be matched with the printed passport page; check its last letter carefully.':'');
      state.passportScan[index]={status:'success',message:`Autofilled ${updated} field${updated===1?'':'s'}. Please confirm every value before continuing.${attention}`};
      render();
    }catch(error){
      if(scanNonce[index]!==nonce||state.view!=='travellers')return;
      state.passportScan[index]={status:'error',message:error.message||'Could not read this image. Try a clearer passport photo.'};
      render();
    }
  }
  function travellers(){if(!state.search||state.selected===null)return pageIntro('TRAVEL DETAILS','Start with a flight plan.','Select a flight offer before adding passengers.')+`<section class="section container">${btn('Back to flight search','start','btn btn-primary')}</section>`;const n=state.search.adults+state.search.children+state.search.infants;while(state.travellers.length<n)state.travellers.push({});return `<section class="checkout-section"><div class="container">${progress(2)}<div class="checkout-title"><div class="eyebrow">STEP 02 OF 03</div><h1>Who's traveling?</h1><p>Enter your passenger names for an unconfirmed itinerary preview. Passport details are not sent to the provider.</p></div><div class="checkout-grid"><div><div class="checkout-form-heading">Traveler information <span>${n} ${n===1?'traveler':'travelers'}</span></div>${state.travellers.slice(0,n).map(travellerFields).join('')}${state.error?`<div class="form-error">${esc(state.error)}</div>`:''}<div class="checkout-actions">${btn(ic('chevron-left',17)+' Back to plans','back-results','btn btn-secondary')}${btn('Continue to review '+ic('arrow-right',18),'continue-review','btn btn-primary')}</div></div><aside class="checkout-aside"><h3>Your itinerary</h3>${journeyLegs().map(l=>`<div class="aside-leg"><span>${fmtDate(l.date)}</span><strong>${l.from} ${ic('arrow-right',14)} ${l.to}</strong><small>${esc(airport(l.from).city)} → ${esc(airport(l.to).city)}</small></div>`).join('')}</aside></div></div></section>`;}
  function chosenPlan(){
    const o=resultOptions()[state.selected??0]||resultOptions()[0];
    return {...o,viaCode:['DOH','DXB','IST'][state.selected??0]||'DOH',carrierCode:['QR','EK','TK'][state.selected??0]||'EF'};
  }
  function itineraryData(){
    if(state.live?.status==='ready'&&!state.usingDemo&&state.selected!==null){
      const o=state.live.offers[state.selected];if(!o)throw Error('Selected flight offer not available.');
      const sectors=o.slices.flatMap((sl,si)=>sl.segments.map((seg,j)=>({
        from:{code:seg.origin.code,city:seg.origin.city||seg.origin.name},to:{code:seg.destination.code,city:seg.destination.city||seg.destination.name},
        date:liveDate(seg.departingAt),isoDate:seg.departingAt.slice(0,10),arrivalDate:liveDate(seg.arrivingAt),
        departureTime:liveTime(seg.departingAt),arrivalTime:liveTime(seg.arrivingAt),flightNo:seg.flightNumber||'See provider',
        aircraft:seg.aircraft||'Check with airline',terminalFrom:seg.originTerminal||'Check with airline',terminalTo:seg.destinationTerminal||'Check with airline',
        baggage:seg.baggage||'Check with airline',cabin:state.search.cabin,duration:seg.duration,routeIndex:si+1,operatingAirline:seg.operatingAirline,operatingCode:seg.operatingCode||seg.marketingCode
      })));
      return {liveOffer:true,providerLive:!!state.live.liveMode,carrier:mainCarrier(o),carrierCode:mainCarrierCode(o),plan:'Supplier flight offer',
        bookingReference:`BF-${sampleRef()}`,demoCode:sampleRef(),airlinePnr:'NOT ISSUED',bookingStatus:'UNBOOKED AIRLINE OFFER',
        trip:state.search.trip==='round'?'Round trip':state.search.trip==='multi'?'Multi-city':'One way',cabin:state.search.cabin,generated:fmtDate(today()),
        fareSample:Number(o.amount),fareTotal:Number(o.amount),currency:o.currency,offerExpires:o.expiresAt,
        baggage:sectors[0]?.baggage||'',bookingSource:'Duffel airline offer search · Not a booking',
        travelers:state.travellers.map((x,i)=>({gender:x.gender||'',name:`${x.first||''} ${x.last||''}`.trim().toUpperCase(),dob:x.dob||'',nationality:x.nationality||'',passport:x.passport||'',passportExpiry:x.passportExpiry||'',type:i<state.search.adults?'Adult':i<state.search.adults+state.search.children?'Child':'Infant'})),
        legs:journeyLegs(),segments:sectors
      };
    }
    const chosen=chosenPlan();const legs=journeyLegs();const sectors=legs.flatMap((l,i)=>sampleSectors(l,chosen,i));
    return {
      carrier:chosen.carrier,carrierCode:chosen.carrierCode,plan:chosen.name,
      bookingReference:`BF-${sampleRef()}`,demoCode:sampleRef(),airlinePnr:'NOT ISSUED',bookingStatus:'DEMO / UNCONFIRMED',
      trip:state.search.trip==='round'?'Round trip':state.search.trip==='multi'?'Multi-city':'One way',
      cabin:state.search.cabin,generated:fmtDate(today()),fareSample:chosen.price,
      baggage:chosen.baggage,bookingSource:'Biz-Flights frontend demonstration',
      travelers:state.travellers.map((x,i)=>({gender:x.gender||'',name:`${x.first||''} ${x.last||''}`.trim().toUpperCase(),dob:x.dob||'',nationality:x.nationality||'',passport:x.passport||'',passportExpiry:x.passportExpiry||'',type:i<state.search.adults?'Adult':i<state.search.adults+state.search.children?'Child':'Infant'})),
      legs,segments:sectors
    };
  }
  function printable(){
    const d=itineraryData(),first=d.segments[0],last=d.segments[d.segments.length-1];
    return `<article id="print-sheet" class="print-sheet booking-document" aria-label="Flight itinerary preview">
      
      <header class="doc-head"><div class="doc-brand"><span class="doc-brand-icon">${ic('plane-small',23)}</span><span>biz-<b>flights</b><small>TRAVEL DOCUMENT</small></span></div><div class="ticket-issuing"><strong>FLIGHT ITINERARY</strong><span>Issued as preview · ${esc(d.generated)}</span></div></header>
      <div class="doc-inner">
        <div class="ticket-booking-summary"><div class="booking-ref-heading"><div><span class="ticket-kicker">ITINERARY INFORMATION</span><h2>Your trip details</h2></div><span class="ticket-unconfirmed">${ic('info',14)} NOT CONFIRMED</span></div>
          <div class="ticket-ref-grid"><div><small>Document reference</small><strong>${esc(d.bookingReference)}</strong><em>Biz-Flights demo ID</em></div><div><small>Sample 6-character reference</small><strong class="mono-code">${esc(d.demoCode)}</strong><em>NOT an airline PNR</em></div><div><small>Airline PNR / record locator</small><strong>NOT ISSUED</strong><em>No booking created</em></div><div><small>E-ticket number</small><strong>NOT ISSUED</strong><em>Ticketing unavailable</em></div></div></div>
        <div class="doc-overview booking-route"><div class="doc-endpoint"><strong>${esc(first.from.code)}</strong><span>${esc(first.from.city)}</span></div><div class="doc-journey-connector"><span class="doc-connector-line"></span>${ic('plane-small',20)}<span class="doc-connector-line"></span><small>${esc(d.trip.toUpperCase())}</small></div><div class="doc-endpoint doc-endpoint-arrival"><strong>${esc(d.trip==='Round trip'?d.legs[0].to:last.to.code)}</strong><span>${esc(d.trip==='Round trip'?airport(d.legs[0].to).city:last.to.city)}</span></div></div>
        <div class="doc-facts"><div><small>TRAVELERS</small><strong>${d.travelers.length}</strong></div><div><small>TRIP TYPE</small><strong>${esc(d.trip)}</strong></div><div><small>CLASS</small><strong>${esc(d.cabin)}</strong></div><div><small>DOCUMENT STATUS</small><strong>Sample only</strong></div></div>
        <div class="doc-section-heading"><h3>Flight itinerary</h3><span>${d.segments.length} flight segment(s) · ${d.liveOffer ? "Published airline local times" : "Local times (example)"}</span></div>
        ${d.segments.map((s,i)=>`<section class="doc-flight booking-sector"><div class="doc-flight-top"><div class="doc-carrier">${airlineBadge(d.carrier,d.carrierCode,'doc-carrier-logo')}<div><strong>${esc(d.carrier)} <span class="flight-number">${esc(s.flightNo)}</span></strong><small>SEGMENT ${i+1} OF ${d.segments.length} · ${esc(s.aircraft)} · ${d.liveOffer ? "PROVIDER DETAILS" : "SAMPLE FLIGHT"}</small></div></div><span class="doc-flight-status">${d.liveOffer ? "OFFER · NOT BOOKED" : "SAMPLE · NOT BOOKED"}</span></div>
          <div class="doc-flight-route"><div class="doc-airport"><strong>${esc(s.departureTime)}</strong><b>${esc(s.from.code)}</b><span>${esc(s.from.city)}</span><small>${esc(s.date)} · Terminal TBC</small></div><div class="doc-flight-middle"><span>${ic('plane-small',17)} ${esc(s.duration)}</span><div class="doc-dashed-line"></div><small>${esc(d.cabin)} · ${d.liveOffer ? "Supplier schedule" : "Sample schedule"}</small></div><div class="doc-airport doc-airport-to"><strong>${esc(s.arrivalTime)}</strong><b>${esc(s.to.code)}</b><span>${esc(s.to.city)}</span><small>${esc(s.arrivalDate)} · Terminal TBC</small></div></div>
          <div class="doc-flight-details"><span>FLIGHT ${esc(s.flightNo)}</span><span>${esc(s.aircraft)}</span><span>${esc(d.cabin)}</span><span>BAGGAGE ${esc(s.baggage)}</span></div></section>`).join('')}
        <div class="doc-section-heading"><h3>Passenger details</h3><span>As entered by traveler</span></div>
        <div class="doc-table-wrap"><table class="doc-passenger-table"><thead><tr><th>Full name</th><th>Type</th><th>Passport</th><th>Ticket no.</th></tr></thead><tbody>${d.travelers.map(t=>`<tr><td>${esc(t.name)}</td><td>${esc(t.type)}</td><td>${esc(t.passport||'Not provided')}</td><td>NOT ISSUED</td></tr>`).join('')}</tbody></table></div>
        <div class="ticket-fare-panel"><div><span>Illustrative fare summary</span><strong>${d.liveOffer ? `${esc(d.currency)} ${Number(d.fareTotal).toLocaleString("en-US",{minimumFractionDigits:2})}` : money(d.fareSample*d.travelers.length)}</strong><small>${d.liveOffer ? "Supplier quoted total; availability may change" : "Example fare for layout purposes, not an offer or charge"}</small></div><div><span>Payment status</span><strong>NOT PAID</strong><small>No order or reservation has been placed</small></div></div>
        <div class="doc-warning"><div>${ic('info',19)} <strong>DEMONSTRATION ONLY — NOT A BOOKING CONFIRMATION</strong></div><p>This PDF is a sample itinerary, not an airline ticket, hold, or reservation. The six-character demo code is not an airline PNR. ${d.liveOffer ? "Flight information comes from an airline offer search, but may change before booking." : "Flight numbers, schedules, aircraft, baggage and sample fares are illustrative and unverified."} A real PNR and ticket number require an airline or authorized booking provider. Do not present this document as evidence of a confirmed reservation.</p></div>
        <div class="doc-bottom"><span>Biz-Flights · Travel planning demo</span><span>Generated ${esc(d.generated)} · ${esc(d.bookingReference)}</span></div>
      </div></article>`;
  }
  function review(){if(!state.search||state.selected===null)return pageIntro('TRAVEL ITINERARY','Start with a flight plan.','Choose a sample flight plan to create a document.')+`<section class="section container">${btn('Start planning','start','btn btn-primary')}</section>`;
    return `<section class="checkout-section review-section"><div class="container">${progress(3)}<div class="checkout-title"><div class="eyebrow">YOUR FLIGHT ITINERARY</div><h1>Review your journey.</h1><p>Passenger names, airline segments and travel details appear below in an A4 document. This is not a confirmed booking.</p></div><div class="review-toolbar"><div class="review-tip">${ic('shield',20)} No airline PNR or e-ticket issued · Offer is not booked.</div><div class="review-buttons">${btn(ic('chevron-left',16)+' Edit details','edit-travellers','btn btn-outline btn-sm')}${btn(ic('download',18)+' Download Ticket','download-pdf','btn btn-primary')}${btn(ic('file',17)+' Print','print','btn btn-secondary btn-sm')}</div></div><div id="pdf-feedback" class="pdf-feedback" role="status" aria-live="polite"></div>${printable()}<div class="review-bottom">To provide authentic, verifiable airline PNRs and ticket numbers, connect an authorized flight-booking system that creates real reservations.</div></div></section>`;
  }
  function hotelResults(){if(!state.hotelSearch)return pageIntro('HOTELS','Start planning a <em>great stay.</em>','Select your destination and travel dates.')+`<section class="section container">${btn('Find hotels','start-hotel','btn btn-primary')}</section>`;const h=state.hotelSearch;return pageIntro('ACCOMMODATION PLANNING',`Your stay in <em>${esc(h.city)}.</em>`,'A simple overview to organize accommodation dates and next steps.')+`<section class="section"><div class="container"><div class="hotel-summary">${ic('hotel',28)}<div><h3>${esc(h.city)}</h3><p>${fmtDate(h.checkin)} – ${fmtDate(h.checkout)} · ${h.guests} guest(s)</p></div>${btn('Edit search','start-hotel','btn btn-outline btn-sm')}</div><div class="hotel-demo-info">${ic('info',22)} <div><h3>Live hotel reservations are not enabled yet.</h3><p>A hotel provider API is required to display actual properties, rates and availability or to issue verifiable hotel bookings. The frontend search form is ready for that connection.</p></div></div><div class="hotel-next-grid"><article>${ic('calendar',25)}<h3>Confirm your dates</h3><p>Make sure your stay aligns with the arrival and departure dates on your flight itinerary.</p></article><article>${ic('shield',25)}<h3>Use real reservations</h3><p>Only a booking confirmed by a property or booking platform should be presented as proof of accommodation.</p></article><article>${ic('globe',25)}<h3>Explore local neighborhoods</h3><p>Consider the area, accessibility and travel time to your planned destinations.</p></article></div></div></section>`;}
  function modal(){if(!state.modal)return '';if(state.modal==='compare'){const picked=resultOptions().filter(o=>state.compare.includes(o.i));return `<div class="modal-backdrop" data-action="close-modal"><div class="modal-card compare-modal" role="dialog" aria-modal="true" aria-label="Compare sample flights"><button class="modal-close" data-action="close-modal" aria-label="Close">${ic('close',21)}</button><div class="eyebrow">SIDE BY SIDE</div><h2>Compare flight plans</h2><p>All prices and times are illustrative, not live bookings.</p><div class="comparison-table"><div class="comparison-label"><b>Airline</b><b>Via</b><b>Example duration</b><b>Sample fare</b><b>Baggage</b></div>${picked.map(o=>`<div class="comparison-entry"><strong>${airlineBadge(o.carrier,o.carrierCode)} ${esc(o.carrier)}</strong><span>${esc(o.via)}</span><span>${esc(o.duration)}</span><strong>${money(o.price)}</strong><span>${esc(o.baggage)}</span>${btn('Choose','choose-compare','btn btn-primary btn-sm',`data-plan="${o.i}"`)}</div>`).join('')}</div></div></div>`;}return `<div class="modal-backdrop" data-action="close-modal"><div class="modal-card" role="dialog" aria-modal="true" aria-label="Account access"><button class="modal-close" data-action="close-modal" aria-label="Close">${ic('close',21)}</button><div class="modal-icon">${ic('user',26)}</div><h2>Welcome to Biz-Flights</h2><p>Account login and registration require a secure backend, which is not part of this frontend demo.</p><div class="modal-info">${ic('shield',20)} You can try flight search, traveler details, and a printable travel plan without creating an account.</div>${btn('Continue as guest '+ic('arrow-right',18),'guest','btn btn-primary btn-block')}</div></div>`;}
  const viewRender={home,individuals,agencies,destinations,guides,contact,about,results,travellers,review,'hotel-results':hotelResults,tools,saved,pnr,documents};
  // You2-Biz: a single booking flow (search -> results -> travellers -> review), without the
  // public site's header, footer and other pages. Any other page falls back to the search.
  const flowViews=['home','results','travellers','review','hotel-results'];
  function render(){const root=document.getElementById('app');root.innerHTML=`<main id="main-content" class="you2-flow">${(flowViews.includes(state.view)?viewRender[state.view]?.():null)||home()}</main>`+modal()+(state.toolMessage?`<div class="app-toast" role="status">${ic('check',17)} ${esc(state.toolMessage)} <button type="button" data-action="dismiss-toast" aria-label="Dismiss">${ic('close',16)}</button></div>`:'');document.title=(state.view==='home'?'Biz-Flights | Flight Search & Itineraries':state.view[0].toUpperCase()+state.view.slice(1).replace('-',' ')+' | Plan Your Trip')+' — Biz-Flights';}
  function doSearch(){state.error='';let legs=state.trip==='multi'?state.segments.map(x=>({...x})):state.trip==='round'?[{from:state.from,to:state.to,date:state.departure},{from:state.to,to:state.from,date:state.returnDate}]:[{from:state.from,to:state.to,date:state.departure}];for(let k=0;k<legs.length;k++){const l=legs[k];const f=findAirport(l.from),t=findAirport(l.to);if(!f||!t){state.error=`Please select an airport from the list for flight ${k+1}.`;render();return;}l.from=f.code;l.to=t.code;if(f.code===t.code){state.error='Your origin and destination must be different airports.';render();return;}if(!l.date||l.date<today()){state.error='Choose a valid future departure date.';render();return;}if(k>0&&l.date<legs[k-1].date){state.error='Flight dates must be in chronological order.';render();return;}}
    state.search={trip:state.trip,from:legs[0].from,to:legs[0].to,departure:legs[0].date,returnDate:state.returnDate,segments:legs,adults:state.adults,children:state.children,infants:state.infants,cabin:state.cabin};state.selected=null;state.travellers=[];state.passportScan={};state.routeFilter='all';state.liveStopFilter='all';state.compare=[];state.live={status:'loading',offers:[],after:null,requestId:null,visibleLimit:12,loadingMore:false,error:''};navigate('results');doLiveSearch();}
  function doHotels(){if(!state.hotelCity.trim()){state.error='Enter a city or hotel destination.';render();return;}if(!state.checkin||!state.checkout||state.checkin<today()||state.checkout<=state.checkin){state.error='Choose valid check-in and check-out dates.';render();return;}state.hotelSearch={city:state.hotelCity.trim(),checkin:state.checkin,checkout:state.checkout,guests:state.hotelGuests};state.error='';navigate('hotel-results');}
  function goHome(tab='flight'){state.tab=tab;state.passengersOpen=false;navigate('home');setTimeout(()=>document.getElementById('flight-search')?.scrollIntoView({behavior:'smooth',block:'center'}),30);}
  document.addEventListener('click',async e=>{
    const airportChoice=e.target.closest('[data-airport-select]');if(airportChoice){chooseAirport(airportChoice.dataset.airportTarget,airportChoice.dataset.airportSelect);return;}
const b=e.target.closest('[data-action]');if(!b)return;const act=b.dataset.action;if(act==='close-modal' && b.classList.contains('modal-backdrop') && e.target!==b)return;
    if(act==='save-route'){const q=state.search||{from:state.from,to:state.to,departure:state.departure,returnDate:state.returnDate,trip:state.trip,cabin:state.cabin};const obj={from:q.from,to:q.to,date:q.departure,returnDate:q.trip==='round'?q.returnDate:'',trip:q.trip,cabin:q.cabin};if(!state.savedTrips.some(x=>JSON.stringify(x)===JSON.stringify(obj))){state.savedTrips.unshift(obj);state.savedTrips=state.savedTrips.slice(0,12);storeSaved(state.savedTrips);}state.toolMessage='Route saved on this browser.';render();return;}
    if(act==='saved'){navigate('saved');return;}
    if(act==='use-saved'){const v=state.savedTrips[Number(b.dataset.index)];if(v){state.from=v.from;state.to=v.to;state.departure=v.date;state.returnDate=v.returnDate||addDays(7,v.date);state.trip=v.trip==='multi'?'round':v.trip;state.cabin=v.cabin;goHome();}return;}
    if(act==='remove-saved'){state.savedTrips.splice(Number(b.dataset.index),1);storeSaved(state.savedTrips);render();return;}
    if(act==='reset-checklist'){state.checklist={};try{localStorage.removeItem('ef_checklist')}catch(_){}render();return;}
    if(act==='compare-plan'){const id=Number(b.dataset.plan);state.compare=state.compare.includes(id)?state.compare.filter(x=>x!==id):[...state.compare,id].slice(-3);render();return;}
    if(act==='clear-compare'){state.compare=[];render();return;}
    if(act==='show-compare'){state.modal='compare';render();return;}
    if(act==='choose-compare'){state.selected=Number(b.dataset.plan);state.modal=null;navigate('travellers');return;}
    if(act==='share-route'){const q=state.search;if(!q)return;const link=location.href.split('#')[0]+'#/';const t=`Biz-Flights travel plan: ${q.from} to ${q.to} on ${fmtDate(q.departure)}. Plan your own trip: ${link} (This is not a confirmed reservation.)`;if(navigator.clipboard?.writeText){navigator.clipboard.writeText(t).then(()=>{const f=document.getElementById('pdf-feedback');if(f)f.textContent='Trip summary copied to clipboard.'}).catch(()=>{});}return;}
    if(act==='dismiss-toast'){state.toolMessage='';render();return;}
    if(act==='toggle-menu'){state.mobileMenu=!state.mobileMenu;render();return;}
    if(act==='tab-flight'||act==='tab-hotel'){state.tab=act.slice(4);state.error='';state.passengersOpen=false;render();return;}
    if(act.startsWith('trip-')){state.trip=act.slice(5);state.error='';state.passengersOpen=false;render();return;}
    if(act==='swap'){[state.from,state.to]=[state.to,state.from];render();return;}
    if(act==='toggle-pax'){state.passengersOpen=!state.passengersOpen;render();return;}
    if(act==='pax-plus'||act==='pax-minus'){const key=b.dataset.key;const change=act==='pax-plus'?1:-1;state[key]=Math.max(key==='adults'?1:0,Math.min(9,state[key]+change));if(state.infants>state.adults)state.infants=state.adults;render();return;}
    if(act==='add-seg'){if(state.segments.length<5){const last=state.segments.at(-1);state.segments.push({from:last.to,to:'',date:addDays(3,last.date)});render();}return;}
    if(act==='remove-seg'){if(state.segments.length>2){state.segments.splice(+b.dataset.index,1);render();}return;}
    if(act==='search-flights'){doSearch();return;}
    if(act==='retry-live'){doLiveSearch();return;}
    if(act==='demo-flights'){state.live=null;state.usingDemo=true;render();return;}
    if(act==='load-more-live'){loadMoreFlights();return;}
    if(act==='load-all-live'){loadMoreFlights(true);return;}
    if(act==='show-more-local'){state.live.visibleLimit+=12;render();return;}
    if(act==='clear-live-filters'){state.routeFilter='all';state.liveStopFilter='all';render();return;}
    if(act==='select-live-offer'){selectLiveOffer(Number(b.dataset.plan));return;}
    if(act==='search-hotels'){doHotels();return;}
    if(act==='start'){goHome();return;}
    if(act==='start-hotel'){goHome('hotel');return;}
    if(act==='destination'){state.to=b.dataset.code;state.from='DAC';goHome();return;}
    if(act==='select-plan'){state.selected=Number(b.dataset.plan);navigate('travellers');return;}
    if(act==='back-results'){navigate('results');return;}
    if(act==='continue-review'){if(!state.search)return;let valid=true;for(const t of state.travellers){if(!t.first?.trim()||!t.last?.trim())valid=false;}if(!valid){state.error='Enter the first and last name for each traveler.';render();return;}state.error='';navigate('review');return;}
    if(act==='edit-travellers'){navigate('travellers');return;}
    if(act==='download-pdf'){
      const feedback=document.getElementById('pdf-feedback');
      try{
        if(!window.ExploreFlightsPDF)throw new Error('PDF generator did not load. Try the full ZIP version.');
        const name=await window.ExploreFlightsPDF.download(itineraryData());
        if(feedback)feedback.textContent=`PDF generated: ${name}. Check your browser downloads.`;
      }catch(error){if(feedback)feedback.textContent=`Could not download PDF: ${error.message}`;console.error(error);}
      return;
    }
    if(act==='print'){window.print();return;}
    if(act==='faq'){state.faqOpen=state.faqOpen===+b.dataset.index?-1:+b.dataset.index;render();return;}
    if(act==='login'){state.modal='login';render();return;}
    if(act==='close-modal'||act==='guest'){state.modal=null;render();return;}
    if(['individuals','agencies','destinations','guides','contact','about','tools','saved','pnr','documents'].includes(act)){navigate(act);return;}
  });
  document.addEventListener('change',e=>{if(e.target.matches('[data-passport-photo]')){const input=e.target;const file=input.files?.[0];if(file)scanPassportPhoto(Number(input.dataset.passportPhoto),file);input.value='';return;}if(e.target.matches('[data-checklist]')){state.checklist[e.target.dataset.checklist]=e.target.checked;try{localStorage.setItem('ef_checklist',JSON.stringify(state.checklist))}catch(_){}render();return;}});
  document.addEventListener('input',e=>{let el=e.target;if(el.matches('input[data-airport-entry]')){setAirportState(el.dataset.input,el.value);const hint=el.closest('.airport-field')?.querySelector('.field-hint');if(hint)hint.textContent='Select from airport suggestions';drawAirportSuggestions(el);return;}if(el.hasAttribute('data-traveller')){const idx=+el.dataset.traveller;state.travellers[idx]??={};state.travellers[idx][el.dataset.field]=el.value;return;}
    if(el.dataset.input==='destinationQuery'){const pos=el.selectionStart;state.destinationQuery=el.value;render();const newer=document.querySelector('[data-input="destinationQuery"]');newer?.focus();try{newer?.setSelectionRange(pos,pos);}catch(_){}return;}
    if(el.dataset.input==='hotelCity')state.hotelCity=el.value;
  });
  document.addEventListener('change',e=>{const el=e.target,k=el.dataset.input;if(!k)return;if(k.startsWith('seg-')){const [,index,key]=k.split('-');if(!state.segments[+index])return;state.segments[+index][key]=['from','to'].includes(key)?(findAirport(el.value)?.code||el.value):el.value;return;}
    if(['from','to'].includes(k))state[k]=findAirport(el.value)?.code||el.value;
    else if(['departure','returnDate','checkin','checkout'].includes(k))state[k]=el.value;
    else if(k==='cabin'){state.cabin=el.value;render();}
    else if(k==='routeFilter'||k==='sortBy'||k==='liveStopFilter'){state[k]=el.value;render();}
    else if(k==='hotelGuests')state.hotelGuests=Number(el.value);
  });
  document.addEventListener('submit',async e=>{if(e.target.id!=='contact-form')return;e.preventDefault();const f=new FormData(e.target);const msg=`Biz-Flights inquiry\nFrom: ${f.get('name')}\nEmail: ${f.get('email')}\nTopic: ${f.get('topic')}\n\n${f.get('message')}`;try{await navigator.clipboard.writeText(msg);state.contactFeedback='Inquiry copied! Paste it into your email or messaging app.';}catch(_){state.contactFeedback='Clipboard unavailable. Select and copy your message manually.';}document.querySelector('.form-hint').textContent=state.contactFeedback;});
  window.addEventListener('hashchange',()=>{const dest=location.hash.replace(/^#\/?/,'').split('?')[0]||'home';if(dest!==state.view){state.view=routes.includes(dest)?dest:'home';state.mobileMenu=false;state.error='';render();window.scrollTo(0,0);}});
  const initial=location.hash.replace(/^#\/?/,'').split('?')[0]||'home';state.view=routes.includes(initial)?initial:'home';render();
})();
